48	inline std::string to_string(const DType type) {
49	  switch (type) {
50	    case DType::kByte:
51	      return "Byte";
52	    case DType::kBFloat16:
53	      return "BFloat16";
54	    case DType::kFloat16:
55	      return "Float16";
56	    case DType::kFloat32:
57	      return "Float32";
58	    case DType::kFloat8E4M3:
59	      return "Float8E4M3";
60	    case DType::kFloat8E5M2:
61	      return "Float8E5M2";
62	    case DType::kFloat8E8M0:
63	      return "Float8E8M0";
64	    case DType::kFloat4E2M1:
65	      return "Float4E2M1";
66	    case DType::kInt16:
67	      return "Int16";
68	    case DType::kInt32:
69	      return "Int32";
70	    case DType::kInt64:
71	      return "Int64";
72	    default:
73	      return std::string("Invalid type ") + std::to_string(static_cast<int>(type));
74	  }
75	}
