102	inline size_t product(const std::vector<size_t> &shape, const size_t begin, const size_t end) {
103	  NVTE_CHECK(begin <= end && end <= shape.size(), "Attempted to access entries ", begin, " to ",
104	             end, " in a vector with ", shape.size(), " entries");
105	  size_t ret = 1;
106	  for (size_t i = begin; i < end; ++i) {
107	    ret *= shape[i];
108	  }
109	  return ret;
110	}
111	
112	template <typename Container,
113	          typename = std::enable_if_t<std::is_integral<typename Container::value_type>::value>>
114	inline size_t product(const Container &shape) {
115	  size_t ret = 1;
116	  for (const auto &elem : shape) {
117	    ret *= elem;
118	  }
119	  return ret;
120	}
