126	/*! \brief Tensor shape
127	 *
128	 *  Wraps NVTEShape with an interface similar to std::vector<size_t>.
129	 */
130	class Shape {
131	 public:
132	  using value_type = size_t;
133	  using size_type = size_t;
134	  using iterator = size_t *;
135	  using const_iterator = const size_t *;
136	
137	  /*! Maximum number of dimensions this shape can hold. */
138	  static constexpr size_type max_ndim = std::extent_v<decltype(NVTEShape::data)>;
139	
140	  constexpr Shape() noexcept = default;
141	
142	  explicit constexpr Shape(const NVTEShape &shape) noexcept : data_{shape} {}
143	
144	  Shape(std::initializer_list<size_t> shape) {
145	    NVTE_CHECK(shape.size() <= max_ndim, "Too many dimensions (requested ", shape.size(),
146	               ", max is ", max_ndim, ").");
147	    data_.ndim = shape.size();
148	    std::copy(shape.begin(), shape.end(), data_.data);
149	  }
150	
151	  // Construct from any container of integers
152	  template <typename Container,
153	            typename = std::enable_if_t<std::is_integral<typename Container::value_type>::value>>
154	  explicit Shape(const Container &shape) {
155	    NVTE_CHECK(shape.size() <= max_ndim, "Too many dimensions (requested ", shape.size(),
156	               ", max is ", max_ndim, ").");
157	    data_.ndim = shape.size();
158	    std::copy(shape.begin(), shape.end(), data_.data);
159	  }
160	
161	  constexpr operator NVTEShape() const noexcept { return data_; }
162	
163	  /*! Cast to std::vector */
164	  explicit operator std::vector<size_t>() const {
165	    return std::vector<size_t>(data_.data, data_.data + data_.ndim);
166	  }
167	
168	  constexpr size_type size() const noexcept { return data_.ndim; }
169	  constexpr bool empty() const noexcept { return data_.ndim == 0; }
170	  static constexpr size_type capacity() noexcept { return max_ndim; }
171	
172	  value_type *data() noexcept { return data_.data; }
173	  constexpr const value_type *data() const noexcept { return data_.data; }
174	
175	  iterator begin() noexcept { return data_.data; }
176	  constexpr const_iterator begin() const noexcept { return data_.data; }
177	  constexpr const_iterator cbegin() const noexcept { return data_.data; }
178	  iterator end() noexcept { return data_.data + data_.ndim; }
179	  constexpr const_iterator end() const noexcept { return data_.data + data_.ndim; }
180	  constexpr const_iterator cend() const noexcept { return data_.data + data_.ndim; }
181	
182	  const value_type &at(size_type i) const {
183	    NVTE_CHECK(i < data_.ndim, "Attempted to access out-of-bounds entry (requested ", i,
184	               ", size is ", data_.ndim, ").");
185	    return data_.data[i];
186	  }
187	  value_type &at(size_type i) { return const_cast<value_type &>(std::as_const(*this).at(i)); }
188	
189	  value_type &operator[](size_type i) noexcept { return data_.data[i]; }
190	  constexpr const value_type &operator[](size_type i) const noexcept { return data_.data[i]; }
191	
192	  value_type &front() noexcept { return data_.data[0]; }
193	  constexpr const value_type &front() const noexcept { return data_.data[0]; }
194	
195	  value_type &back() noexcept { return data_.data[data_.ndim - 1]; }
196	  constexpr const value_type &back() const noexcept { return data_.data[data_.ndim - 1]; }
197	
198	  void push_back(size_type value) {
199	    NVTE_CHECK(data_.ndim < max_ndim, "Cannot add dimension: shape is at maximum capacity (",
200	               max_ndim, ").");
201	    data_.data[data_.ndim++] = value;
202	  }
203	
204	  void resize(size_type count) {
205	    NVTE_CHECK(count <= max_ndim, "Too many dimensions (requested ", count, ", max is ", max_ndim,
206	               ").");
207	    if (count > data_.ndim) {
208	      std::fill(&data_.data[data_.ndim], &data_.data[count], 0);
209	    }
210	    data_.ndim = count;
211	  }
212	
213	  void clear() noexcept { data_.ndim = 0; }
214	
215	  friend bool operator==(const Shape &lhs, const Shape &rhs) noexcept {
216	    return lhs.data_.ndim == rhs.data_.ndim &&
217	           std::equal(lhs.data_.data, lhs.data_.data + lhs.data_.ndim, rhs.data_.data);
218	  }
219	  friend bool operator!=(const Shape &lhs, const Shape &rhs) noexcept { return !(lhs == rhs); }
220	
221	  template <typename Container,
222	            typename = std::enable_if_t<std::is_integral<typename Container::value_type>::value>>
223	  friend bool operator==(const Shape &lhs, const Container &rhs) {
224	    return lhs == Shape(rhs);
225	  }
226	  template <typename T>
227	  friend bool operator==(const T &lhs, const Shape &rhs) {
228	    return rhs == lhs;
229	  }
230	  template <typename T>
231	  friend bool operator!=(const Shape &lhs, const T &rhs) {
232	    return !(lhs == rhs);
233	  }
234	  template <typename T>
235	  friend bool operator!=(const T &lhs, const Shape &rhs) {
236	    return !(rhs == lhs);
237	  }
238	
239	 private:
240	  NVTEShape data_{};
241	};
