243	struct SimpleTensor {
244	  void *dptr;
245	  Shape shape;
246	  DType dtype;
247	
248	  SimpleTensor(void *dptr, std::vector<size_t> shape, DType dtype)
249	      : dptr{dptr}, shape(shape), dtype{dtype} {}
250	
251	  SimpleTensor() : SimpleTensor(nullptr, {0}, DType::kFloat32) {}
252	
253	  SimpleTensor(const NVTEBasicTensor &tensor)  // NOLINT
254	      : dptr(tensor.data_ptr), shape(tensor.shape), dtype(static_cast<DType>(tensor.dtype)) {}
255	
256	  operator NVTEBasicTensor() const {
257	    return {dptr, static_cast<NVTEDType>(dtype), static_cast<NVTEShape>(shape)};
258	  }
259	
260	  /*! Number of tensor elements. */
261	  size_t numel() const { return product(shape); }
262	
263	  /*! Whether the tensor is initialized.
264	   *
265	   *  Tensors with non-trivial shapes are considered initialized. This
266	   *  means that there is no guarantee that the data pointer can be
267	   *  safely accessed.
268	   */
269	  bool has_data() const { return !(dptr == nullptr && shape.size() == 1 && shape[0] == 0); }
270	
271	  /*! Buffer size in bytes. */
272	  size_t buffer_size_bytes() const { return get_buffer_size_bytes(numel(), dtype); }
273	
274	  /*! Reset to uninitialized tensor. */
275	  void clear() {
276	    dptr = nullptr;
277	    shape.resize(1);
278	    shape[0] = 0;
279	    dtype = DType::kFloat32;
280	  }
281	};
