283	struct Tensor {
284	 public:
285	  SimpleTensor data;
286	  SimpleTensor columnwise_data;
287	  SimpleTensor amax;
288	  SimpleTensor columnwise_amax;
289	  SimpleTensor scale;
290	  SimpleTensor scale_inv;
291	  SimpleTensor columnwise_scale_inv;
292	
293	  NVTEScalingMode scaling_mode;
294	  NVTETensor nvte_tensor;
295	  /*! \brief Whether scaling factors are in format expected by GEMM
296	   *
297	   *  Only meaningful for MXFP8 and NVFP4.
298	   */
299	  bool with_gemm_swizzled_scales = false;
300	  /*! \brief Whether NVFP4 rowwise amax metadata is row-scaled.
301	   *
302	   *  Only meaningful for NVFP4 tensors.
303	   */
304	  bool row_scaled_nvfp4 = false;
305	  /*! \brief Global E4M3 scale bound used by NVFP4.
306	   *
307	   *  Standard NVFP4 uses 448. Some 4over6 tensors use 256 to leave room for
308	   *  map-to-4 local scale expansion.
309	   */
310	  int nvfp4_e4m3_max = 448;
311	
312	  /*! Map from NVTETensorParam to parameter sizes */
313	  static constexpr size_t attr_sizes[] = {
314	      sizeof(NVTEBasicTensor),  // kNVTERowwiseData
315	      sizeof(NVTEBasicTensor),  // kNVTEColumnwiseData
316	      sizeof(NVTEBasicTensor),  // kNVTEScale
317	      sizeof(NVTEBasicTensor),  // kNVTEAmax
318	      sizeof(NVTEBasicTensor),  // kNVTERowwiseScaleInv
319	      sizeof(NVTEBasicTensor),  // kNVTEColumnwiseScaleInv
320	      sizeof(NVTEBasicTensor),  // kNVTEColumnwiseAmax
321	      sizeof(uint8_t),          // kNVTEWithGEMMSwizzledScales
322	      sizeof(uint8_t),          // kNVTERowScaledNVFP4
323	      sizeof(int)               // kNVTENVFP4E4M3Max
324	  };
325	
326	  Tensor() : scaling_mode{NVTE_DELAYED_TENSOR_SCALING}, nvte_tensor{0} {}
327	
328	  /*! Reset tensor data. */
329	  void clear() {
330	    data.clear();
331	    columnwise_data.clear();
332	    amax.clear();
333	    columnwise_amax.clear();
334	    scale.clear();
335	    scale_inv.clear();
336	    columnwise_scale_inv.clear();
337	    scaling_mode = NVTE_DELAYED_TENSOR_SCALING;
338	    with_gemm_swizzled_scales = false;
339	    row_scaled_nvfp4 = false;
340	    nvfp4_e4m3_max = 448;
341	  }
342	
343	  explicit operator NVTETensor() const noexcept { return nvte_tensor; }
344	
345	  /*! Number of tensor elements. */
346	  size_t numel() const { return product(shape()); }
347	
348	  /*! Whether the tensor data buffer is not uninitialized.
349	   *
350	   *  Buffers with non-trivial shapes are considered initialized. This
351	   *  means that there is no guarantee that the data pointer can be
352	   *  safely accessed.
353	   */
354	  bool has_data() const { return data.has_data(); }
355	
356	  /*! Whether the tensor column-wise data buffer is not uninitialized.
357	   *
358	   *  Buffers with non-trivial shapes are considered initialized. This
359	   *  means that there is no guarantee that the data pointer can be
360	   *  safely accessed.
361	   */
362	  bool has_columnwise_data() const { return columnwise_data.has_data(); }
363	
364	  /*! Datatype of tensor elements. */
365	  DType dtype() const {
366	    if (!has_data() && has_columnwise_data()) {
367	      return columnwise_data.dtype;
368	    }
369	    return data.dtype;
370	  }
371	
372	  /*! Number of tensor dimensions. */
373	  size_t dim() const {
374	    if (!has_data() && has_columnwise_data()) {
375	      return columnwise_data.shape.size();
376	    }
377	    return data.shape.size();
378	  }
379	
380	  /*! Tensor dimensions.
381	   *
382	   *  This is the logical tensor shape. The underlying data may have a
383	   *  different shape, e.g. the column-wise data for some tensor
384	   *  formats are transposed.
385	   */
386	  Shape shape() const {
387	    // Each tensor format interprets its data differently
388	    switch (scaling_mode) {
389	      case NVTE_DELAYED_TENSOR_SCALING:
390	      case NVTE_BLOCK_SCALING_1D:
391	      case NVTE_BLOCK_SCALING_2D:
392	      case NVTE_NVFP4_1D_SCALING: {
393	        // Row-wise data shape matches tensor logical shape,
394	        // column-wise data shape is transpose of logical shape
395	        if (!has_data() && has_columnwise_data()) {
396	          Shape ret;
397	          if (!columnwise_data.shape.empty()) {
398	            for (size_t i = 1; i < columnwise_data.shape.size(); i++) {
399	              ret.push_back(columnwise_data.shape[i]);
400	            }

400	            }
401	            ret.push_back(columnwise_data.shape.front());
402	          }
403	          return ret;
404	        }
405	        return data.shape;
406	      }
407	      case NVTE_MXFP8_1D_SCALING: {
408	        // Row-wise and column-wise data shapes both match tensor
409	        // logical shape
410	        if (!has_data() && has_columnwise_data()) {
411	          return columnwise_data.shape;
412	        }
413	        return data.shape;
414	      }
415	      default:
416	        NVTE_ERROR("Cannot parse tensor shape with scaling mode \"", to_string(scaling_mode), "\"");
417	    }
418	  }
419	
420	  /*! Matrix dimensions after flattening tensor to 2D.
421	   *
422	   * If a tensor has dimensions (D1, D2, ..., Dn), it is reinterpreted
423	   * as a (D1*D2*...*D(n-1), Dn) matrix.
424	   */
425	  std::array<size_t, 2> flat_2d_dims() const {
426	    const auto s = shape();
427	    if (s.empty()) {
428	      return {1, 1};
429	    }
430	    size_t first_dim = 1;
431	    for (size_t i = 0; i + 1 < s.size(); ++i) {
432	      first_dim *= s[i];
433	    }
434	    return {first_dim, s.back()};
435	  }
436	
437	  /*! Matrix height after tensor is flattened to 2D
438	   *
439	   * If a tensor has dimensions (D1, D2, ..., Dn), it is reinterpreted
440	   * as a (D1*D2*...*D(n-1), Dn) matrix.
441	   */
442	  size_t flat_first_dim() const { return flat_2d_dims()[0]; }
443	
444	  /*! Matrix width after tensor is flattened to 2D
445	   *
446	   * If a tensor has dimensions (D1, D2, ..., Dn), it is reinterpreted
447	   * as a (D1*D2*...*D(n-1), Dn) matrix.
448	   */
449	  size_t flat_last_dim() const { return flat_2d_dims()[1]; }
450	};
