452	struct GroupedTensor {
453	 public:
454	  /* EXPERIMENTAL FEATURE AND SUBJECT TO CHANGE. */
455	  /*
456	  Grouped tensor is a collection of tensors with different shapes but the same dtype and scaling mode
457	
458	  Shape Representation:
459	  - logical_shape: 2D shape representing the conceptual layouy, i.e. the shape when member tensors are flattened to 2D and stacked together (REQUIRED)
460	    + When all_same_shape(): [num_tensors * M, N] where each tensor is (M, N)
461	    + When varying_first_dim(): [~sum_of_first_dims, N] where N is common
462	    + When varying_last_dim(): [M, ~sum_of_last_dims] where M is common
463	    + When varying_both_dims(): [1, total_elements] (fully flattened)
464	
465	  - first_dims and last_dims are OPTIONAL (empty if dimension is uniform)
466	    + Empty first_dims: all tensors have the same first dimension
467	    + Empty last_dims: all tensors have the same last dimension
468	    + Both empty: all tensors have identical shapes
469	    + Both set: each tensor has unique shape (first_dims[i], last_dims[i])
470	
471	  Data Layout:
472	  - ALL data fields are stored as 1D flattened arrays (data, columnwise_data, scale_inv, etc.)
473	  - logical_shape provides the conceptual 2D interpretation
474	  - All data is stored on device in contiguous layout
475	  */
476	
477	  SimpleTensor data;
478	  SimpleTensor columnwise_data;
479	  SimpleTensor scale_inv;
480	  SimpleTensor columnwise_scale_inv;
481	  SimpleTensor amax;
482	  SimpleTensor columnwise_amax;
483	  SimpleTensor scale;  // for FP8-DS only
484	
485	  NVTEScalingMode scaling_mode;
486	  size_t num_tensors;
487	
488	  // Shape information (OPTIONAL - empty if dimension is uniform across all tensors)
489	  // first_dims[i] = first dimension of tensor i (empty if all tensors have same first dim)
490	  // last_dims[i] = last dimension of tensor i (empty if all tensors have same last dim)
491	  SimpleTensor first_dims;  // Device pointer to int64_t array of length num_tensors (or empty)
492	  SimpleTensor last_dims;   // Device pointer to int64_t array of length num_tensors (or empty)
493	
494	  // Offsets for indexing into contiguous 1D layout (OPTIONAL - not needed if all_same_shape())
495	  // tensor_offsets[i] = element offset to start of tensor i (cumulative sum of numel for tensors 0..i-1)
496	  // Usage: tensor_i_ptr = (char*)data.dptr + tensor_offsets[i] * element_size
497	  // If empty and all_same_shape(): offset[i] = i * M * N (where M, N are common dimensions)
498	  SimpleTensor tensor_offsets;  // Device pointer to int64_t array of length num_tensors (or empty)
499	
500	  // Logical shape: conceptual 2D shape of the grouped data (REQUIRED)
501	  // Represents how the 1D flattened data should be interpreted as 2D
502	  // Always 2D with positive dimensions
503	  NVTEShape logical_shape;
504	
505	  NVTEGroupedTensor nvte_tensor;
506	
507	  /*! \brief Whether scaling factors are in format expected by GEMM
508	   *
509	   *  Only meaningful for MXFP8 and NVFP4.
510	   */
511	  bool with_gemm_swizzled_scales = false;
512	
513	  /*! Map from NVTEGroupedTensorParam to parameter sizes */
514	  static constexpr size_t attr_sizes[] = {
515	      sizeof(NVTEBasicTensor),  // kNVTEGroupedRowwiseData
516	      sizeof(NVTEBasicTensor),  // kNVTEGroupedColumnwiseData
517	      sizeof(NVTEBasicTensor),  // kNVTEGroupedScale
518	      sizeof(NVTEBasicTensor),  // kNVTEGroupedAmax
519	      sizeof(NVTEBasicTensor),  // kNVTEGroupedRowwiseScaleInv
520	      sizeof(NVTEBasicTensor),  // kNVTEGroupedColumnwiseScaleInv
521	      sizeof(NVTEBasicTensor),  // kNVTEGroupedColumnwiseAmax
522	      sizeof(NVTEBasicTensor),  // kNVTEGroupedFirstDims
523	      sizeof(NVTEBasicTensor),  // kNVTEGroupedLastDims
524	      sizeof(NVTEBasicTensor),  // kNVTEGroupedTensorOffsets
525	      sizeof(uint8_t)           // kNVTEGroupedWithGEMMSwizzledScales
526	  };
527	
528	  GroupedTensor(NVTEScalingMode scaling_mode, size_t num_tensors)
529	      : data(),
530	        columnwise_data(),
531	        scale_inv(),
532	        columnwise_scale_inv(),
533	        amax(),
534	        columnwise_amax(),
535	        scale(),
536	        scaling_mode(scaling_mode),
537	        num_tensors(num_tensors),
538	        first_dims(nullptr, std::vector<size_t>{0}, DType::kInt64),
539	        last_dims(nullptr, std::vector<size_t>{0}, DType::kInt64),
540	        tensor_offsets(nullptr, std::vector<size_t>{0}, DType::kInt64),
541	        logical_shape(nvte_make_shape(nullptr, 1)),
542	        nvte_tensor(0),
543	        with_gemm_swizzled_scales(false) {}
544	
545	  explicit operator NVTEGroupedTensor() const noexcept { return nvte_tensor; }
546	
547	  bool has_data() const noexcept { return data.has_data(); }
548	  bool has_columnwise_data() const noexcept { return columnwise_data.has_data(); }
549	
550	  bool all_same_first_dim() const noexcept { return !first_dims.has_data(); }
551	  bool all_same_last_dim() const noexcept { return !last_dims.has_data(); }
552	  bool all_same_shape() const noexcept { return !first_dims.has_data() && !last_dims.has_data(); }
553	  bool varying_both_dims() const noexcept { return first_dims.has_data() && last_dims.has_data(); }
554	
555	  size_t get_common_first_dim() const {
556	    NVTE_CHECK(all_same_first_dim(), "First dim varies across tensors");
557	    NVTE_CHECK(logical_shape.ndim == 2, "Logical shape must be 2D");
558	    if (all_same_shape()) {
559	      // When both dims are uniform: logical_shape = [num_tensors * M, N]
560	      return logical_shape.data[0] / num_tensors;
561	    } else {
562	      // When varying last dims but not first dim: logical_shape = [M, sum_of_last_dims]
563	      return logical_shape.data[0];
564	    }
565	  }
566	  size_t get_common_last_dim() const {
567	    NVTE_CHECK(all_same_last_dim(), "Last dim varies across tensors");
568	    NVTE_CHECK(logical_shape.ndim == 2, "Logical shape must be 2D");
569	    // For both uniform and varying first dim cases: logical_shape[1] is the common last dim
570	    return logical_shape.data[1];
571	  }
