633	template <typename T1, typename T2>
634	constexpr __device__ __host__ __forceinline__ uint64_t DIVUP_TO_MULTIPLE(const T1 &N, const T2 &M) {
635	  static_assert(std::is_integral<T1>::value && std::is_integral<T2>::value,
