63	constexpr size_t kThreadsPerBlock = 256;
64	
65	template <typename TVectorized>
66	__global__ void __launch_bounds__(kThreadsPerBlock)
67	    memset_kernel(void *__restrict__ ptr, int value, size_t size_in_bytes) {
68	  size_t idx = blockIdx.x * blockDim.x + threadIdx.x;
69	
70	  if (idx * sizeof(TVectorized) >= size_in_bytes) {
71	    return;  // Out of bounds
72	  }
73	
74	  if ((idx + 1) * sizeof(TVectorized) > size_in_bytes) {
75	    // If the buffer size is not an even multiple of the vectorization, manually set the remaining bytes unvectorized.
76	    size_t remaining_bytes = size_in_bytes - idx * sizeof(TVectorized);
77	    memset(reinterpret_cast<uint8_t *>(ptr) + idx * sizeof(TVectorized), value, remaining_bytes);
78	    return;
79	  }
80	
81	  union {
82	    TVectorized value;
83	    uint8_t data[sizeof(TVectorized)];
84	  } data;
85	  for (size_t i = 0; i < sizeof(TVectorized); ++i) {
86	    data.data[i] = static_cast<uint8_t>(value);
87	  }
88	  reinterpret_cast<TVectorized *>(ptr)[idx] = data.value;
89	}
