93	#define MEMSET_VECTORIZED_KERNEL_DISPATCH(ptr, size_in_bytes, value, vectorizedType, stream) \
94	  if (size_in_bytes >= sizeof(vectorizedType) &&                                             \
95	      reinterpret_cast<size_t>(ptr) % sizeof(vectorizedType) == 0) {                         \
96	    size_t numBlocks = DIVUP(size_in_bytes, kThreadsPerBlock * sizeof(vectorizedType));      \
97	    dim3 grid(numBlocks, 1, 1);                                                              \
98	    memset_kernel<vectorizedType>                                                            \
99	        <<<grid, kThreadsPerBlock, 0, stream>>>(ptr, value, size_in_bytes);                  \
100	    NVTE_CHECK_CUDA(cudaGetLastError());                                                     \
101	    return;                                                                                  \
102	  }
