104	extern "C" {
105	void nvte_memset(void *ptr, int value, size_t size_in_bytes, cudaStream_t stream) {
106	  NVTE_API_CALL(nvte_memset);
107	  NVTE_CHECK(ptr != nullptr, "Pointer for memset must be allocated.");
108	
109	  if (size_in_bytes > 4096) {
110	    // Use cudaMemsetAsync for larger sizes.
111	    NVTE_CHECK_CUDA(cudaMemsetAsync(ptr, value, size_in_bytes, stream));
112	    return;
113	  }
114	
115	  MEMSET_VECTORIZED_KERNEL_DISPATCH(ptr, size_in_bytes, value, float4, stream);
116	  MEMSET_VECTORIZED_KERNEL_DISPATCH(ptr, size_in_bytes, value, float2, stream);
117	  MEMSET_VECTORIZED_KERNEL_DISPATCH(ptr, size_in_bytes, value, float, stream);
118	  MEMSET_VECTORIZED_KERNEL_DISPATCH(ptr, size_in_bytes, value, uint8_t, stream);
119	}
