123	void checkCuDriverContext(CUstream stream) {
124	  // Ensure the thread's "current" CUDA context is set.
125	  cuda_driver::ensure_context_exists();
126	
127	  CUcontext ctx;
128	  const CUresult driver_status = cuda_driver::call("cuStreamGetCtx", stream, &ctx);
129	  switch (driver_status) {
130	    case CUDA_SUCCESS:
131	      break;
132	
133	    case CUDA_ERROR_INVALID_CONTEXT:
134	      int current_device;
135	      NVTE_CHECK_CUDA(cudaGetDevice(&current_device));
136	      NVTE_CALL_CHECK_CUDA_DRIVER(cuDevicePrimaryCtxRetain, &ctx, current_device);
137	      NVTE_CALL_CHECK_CUDA_DRIVER(cuCtxSetCurrent, ctx);
138	      break;
139	
140	    default:
141	      const char *desc_NVTE_CHECK_CUDA_DRIVER;
142	      cuda_driver::call("cuGetErrorString", driver_status, &desc_NVTE_CHECK_CUDA_DRIVER);
143	      NVTE_ERROR("CUDA Error: ", desc_NVTE_CHECK_CUDA_DRIVER);
144	  }
145	}
