165	// Set up parameters to create TMA descriptor.
166	void create_2D_tensor_map(CUtensorMap &tensorMap, const SimpleTensor &tensor,
167	                          const uint64_t globalY, const uint64_t globalX, const uint32_t shmemY,
168	                          const uint32_t shmemX, const uint32_t stride_elems,
169	                          const uint32_t offset_elems, const size_t type_num_bits,
170	                          const CUtensorMapSwizzle swizzle) {
171	  cuda_driver::ensure_context_exists();
172	  // Get a function pointer to the cuTensorMapEncodeTiled driver API
173	  // Note: PFN_cuTensorMapEncodeTiled is not defined in cuda13
174	  static PFN_cuTensorMapEncodeTiled_v12000 cuDriverTensorMapEncodeTiled = []() {
175	    void *driver_ptr = cuda_driver::get_symbol("cuTensorMapEncodeTiled");
176	    return reinterpret_cast<PFN_cuTensorMapEncodeTiled_v12000>(driver_ptr);
177	  }();
178	  // rank is the number of dimensions of the array
179	  constexpr uint32_t rank = 2;
180	
181	  // Dimension for the packed data types must reflect the number of individual U# values.
182	  uint64_t size[rank] = {globalX, globalY};
183	
184	  // The stride is the number of bytes to traverse from the first element of one row to the next
185	  uint64_t stride[rank - 1] = {(stride_elems * type_num_bits) / 8};
186	
187	  // The boxSize is the size of the shared memory buffer that is used as the
188	  // source/destination of a TMA transfer
189	  uint32_t boxSize[rank] = {shmemX, shmemY};
190	
191	  // The distance between elements in units of sizeof(element)
192	  uint32_t elemStride[rank] = {1, 1};
193	
194	  const CUtensorMapDataType tensorDataType = get_CUtensorMapDataType(tensor.dtype);
195	  void *dataPtr = reinterpret_cast<void *>(reinterpret_cast<uint8_t *>(tensor.dptr) +
196	                                           (offset_elems * type_num_bits) / 8);
197	
198	  NVTE_CHECK(is_aligned_ptr(dataPtr, TMA_GMEM_ALIGNMENT),
199	             "Tensor data pointer must be 16B aligned");
200	
201	  const int TMA_needed_size = (TMA_GMEM_ALIGNMENT * 8) / type_num_bits;
202	  NVTE_CHECK(globalX % TMA_needed_size == 0, "Shape not supported. For ", type_num_bits,
203	             "-bit data type, expected multiple of ", TMA_needed_size, ", got ", globalX);
204	
205	  // Create the tensor descriptor.
206	  NVTE_CHECK_CUDA_DRIVER(cuDriverTensorMapEncodeTiled(
207	      &tensorMap,  // CUtensorMap *tensorMap,
208	      tensorDataType,
209	      rank,        // cuuint32_t tensorRank,
210	      dataPtr,     // void *globalAddress,
211	      size,        // const cuuint64_t *globalDim,
212	      stride,      // const cuuint64_t *globalStrides,
213	      boxSize,     // const cuuint32_t *boxDim,
214	      elemStride,  // const cuuint32_t *elementStrides,
215	      // Interleave patterns can be used to accelerate loading of values that
216	      // are less than 4 bytes long.
217	      CUtensorMapInterleave::CU_TENSOR_MAP_INTERLEAVE_NONE,
218	
219	      // Swizzling can be used to avoid shared memory bank conflicts.
220	      swizzle,
221	
222	      // L2 Promotion can be used to widen the effect of a cache-policy to a wider
223	      // set of L2 cache lines.
224	      CUtensorMapL2promotion::CU_TENSOR_MAP_L2_PROMOTION_NONE,
225	      // CUtensorMapL2promotion::CU_TENSOR_MAP_L2_PROMOTION_L2_256B,
226	
227	      // Any element that is outside of bounds will be set to zero by the TMA transfer.
228	      CUtensorMapFloatOOBfill::CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE));
229	}
