238	                                                        size_t outer_size, size_t inner_size) {
239	  std::vector<std::vector<Tensor *>> ret;
240	  for (size_t i = 0; i < outer_size; ++i) {
241	    ret.emplace_back();
242	    for (size_t j = 0; j < inner_size; ++j) {
243	      ret.back().push_back(convertNVTETensor(nvte_tensors[i][j]));
244	    }
245	  }
246	  return ret;
247	}
248	
249	size_t get_buffer_size_bytes(const size_t elements_num, const DType buffer_dtype) {
250	  return (elements_num * typeToNumBits(buffer_dtype)) / 8;
251	}
252	
253	size_t get_buffer_size_bytes(const size_t dim_first, const size_t dim_last,
254	                             const DType buffer_dtype) {
255	  if (buffer_dtype == DType::kFloat4E2M1) {
256	    NVTE_CHECK(dim_last % 2 == 0,
257	               "Last dimension of a tensor with FP4 type of data must be an even number!");
258	  }
259	  const size_t elements_num = dim_first * dim_last;
260	  return get_buffer_size_bytes(elements_num, buffer_dtype);
261	}
