68	void CheckScaleTensorShape(const Tensor &t, std::string_view name) {
69	  NVTE_CHECK(t.scaling_mode != NVTE_INVALID_SCALING, "Invalid scaling mode!");
70	  if (is_tensor_scaling(t.scaling_mode)) {
71	    if (is_fp8_dtype(t.dtype())) {
72	      // FP8 tensor with tensor scaling
73	      if (t.has_data()) {
74	        NVTE_CHECK(t.scale_inv.numel() == 1, "Tensor \"", name,
75	                   "\" has invalid scale_inv shape (expected 1 entry, got ", t.scale_inv.shape,
76	                   ")");
77	      }
78	      if (t.has_columnwise_data()) {
79	        NVTE_CHECK(t.columnwise_scale_inv.numel() == 1, "Tensor \"", name,
80	                   "\" has invalid columnwise_scale_inv shape (expected 1 entry, got ",
81	                   t.columnwise_scale_inv.shape, ")");
82	      }
83	    } else {
84	      // High-precision tensor
85	      if (t.has_data()) {
86	        NVTE_CHECK(t.scale_inv.numel() == 0, "Tensor \"", name,
87	                   "\" has invalid scale_inv shape (expected 0 entries, got ", t.scale_inv.shape,
88	                   ")");
89	      }
90	      if (t.has_columnwise_data()) {
91	        NVTE_CHECK(t.columnwise_scale_inv.numel() == 0, "Tensor \"", name,
92	                   "\" has invalid columnwise_scale_inv shape (expected 0 entries, got ",
93	                   t.columnwise_scale_inv.shape, ")");
94	      }
95	    }
96	  } else {
97	    if (t.scaling_mode == NVTE_MXFP8_1D_SCALING) {
98	      // Need (4, 128) alignment even for e8 scaling factor
99	      constexpr std::array<size_t, 2> block_alignment{128ul, 4ul};
100	      const auto [first_dim, last_dim] = t.flat_2d_dims();
101	
102	      if (t.has_data()) {
103	        constexpr std::array<size_t, 2> block_shape{1, 32};
104	        const std::array<size_t, 2> expected{
105	            DIVUP_TO_MULTIPLE(DIVUP(first_dim, block_shape[0]), block_alignment[0]),
106	            DIVUP_TO_MULTIPLE(DIVUP(last_dim, block_shape[1]), block_alignment[1])};
107	        NVTE_CHECK(t.scale_inv.shape == expected, "Tensor \"", name,
108	                   "\" has invalid scale_inv shape (expected ", expected, ", got ",
109	                   t.scale_inv.shape, ")");
110	      }
111	      if (t.has_columnwise_data()) {
112	        constexpr std::array<size_t, 2> block_shape{32, 1};
113	        const std::array<size_t, 2> expected{
114	            DIVUP_TO_MULTIPLE(DIVUP(first_dim, block_shape[0]), block_alignment[1]),
115	            DIVUP_TO_MULTIPLE(DIVUP(last_dim, block_shape[1]), block_alignment[0])};
116	        NVTE_CHECK(t.columnwise_scale_inv.shape == expected, "Tensor \"", name,
117	                   "\" has invalid columnwise_scale_inv shape (expected ", expected, ", got ",
118	                   t.columnwise_scale_inv.shape, ")");
119	      }
120	    } else if (t.scaling_mode == NVTE_NVFP4_1D_SCALING) {
121	      const auto [first_dim, last_dim] = t.flat_2d_dims();
122	
123	      if (t.has_data()) {
124	        constexpr std::array<size_t, 2> block_shape{1, 16};
125	        constexpr std::array<size_t, 2> block_alignment{128, 4};
126	        const std::array<size_t, 2> expected{
127	            DIVUP_TO_MULTIPLE(DIVUP(first_dim, block_shape[0]), block_alignment[0]),
128	            DIVUP_TO_MULTIPLE(DIVUP(last_dim, block_shape[1]), block_alignment[1])};
129	        NVTE_CHECK(t.scale_inv.shape == expected, "Tensor \"", name,
130	                   "\" has invalid scale_inv shape (expected ", expected, ", got ",
131	                   t.scale_inv.shape, ")");
132	      }
133	      if (t.has_columnwise_data()) {
134	        constexpr std::array<size_t, 2> block_shape{1, 16};
135	        constexpr std::array<size_t, 2> block_alignment{128, 4};
136	        const std::array<size_t, 2> expected{
137	            DIVUP_TO_MULTIPLE(DIVUP(last_dim, block_shape[0]), block_alignment[0]),
138	            DIVUP_TO_MULTIPLE(DIVUP(first_dim, block_shape[1]), block_alignment[1])};
139	        NVTE_CHECK(t.columnwise_scale_inv.shape == expected, "Tensor \"", name,
140	                   "\" has invalid columnwise_scale_inv shape (expected ", expected, ", got ",
141	                   t.columnwise_scale_inv.shape, ")");
142	      }
143	    }
144	  }
145	}
