147	void CheckInputTensor(const Tensor &t, std::string_view name, bool check_scale_inv_shapes) {
148	  const DType type = t.dtype();
149	  if (is_fp8_dtype(type)) {
150	    // FP8 input needs to have scale_inv
151	    if (t.has_data()) {
152	      NVTE_CHECK(t.scale_inv.has_data(), "FP8 scaling factor input ", name,
153	                 "_scale_inverse must be allocated");
154	      NVTE_CHECK(t.scale_inv.dtype == DType::kFloat32 || t.scale_inv.dtype == DType::kFloat8E8M0,
155	                 "FP8 scaling factor input ", name,
156	                 "_scale_inverse has invalid dtype "
157	                 "(expected Float32 or Byte, got ",
158	                 to_string(t.scale_inv.dtype), ")");
159	    }
160	    if (t.has_columnwise_data()) {
161	      NVTE_CHECK(t.columnwise_scale_inv.has_data(), "FP8 scaling factor input ", name,
162	                 "_columnwise_scale_inverse must be allocated");
163	      NVTE_CHECK(t.columnwise_scale_inv.dtype == DType::kFloat32 ||
164	                     t.columnwise_scale_inv.dtype == DType::kFloat8E8M0,
165	                 "FP8 scaling factor input ", name,
166	                 "_columnwise_scale_inverse has invalid dtype "
167	                 "(expected Float32 or Byte, got ",
168	                 to_string(t.columnwise_scale_inv.dtype), ")");
169	    }
170	  } else if (is_fp4_dtype(type)) {
171	    // TODO(ksivaman): Fix this to check for amaxes and other details.
172	    // For now only needed for swizzle.
173	    if (t.has_data()) {
174	      NVTE_CHECK(t.scale_inv.has_data(), "FP4 scaling factor input ", name,
175	                 "_scale_inverse must be allocated");
176	      NVTE_CHECK(t.scale_inv.dtype == DType::kFloat8E4M3, "FP4 scaling factor input ", name,
177	                 "_scale_inverse has invalid dtype "
178	                 "(expected DType::kFloat8E4M3, got ",
179	                 to_string(t.scale_inv.dtype), ")");
180	    }
181	    if (t.has_columnwise_data()) {
182	      NVTE_CHECK(t.columnwise_scale_inv.has_data(), "FP4 scaling factor input ", name,
183	                 "_columnwise_scale_inverse must be allocated");
184	      NVTE_CHECK(t.columnwise_scale_inv.dtype == DType::kFloat8E4M3, "FP8 scaling factor input ",
185	                 name,
186	                 "_columnwise_scale_inverse has invalid dtype "
187	                 "(expected DType::kFloat8E4M3, got ",
188	                 to_string(t.columnwise_scale_inv.dtype), ")");
189	    }
190	  } else {
191	    NVTE_CHECK(!t.scale.has_data(), "Scale is not supported for non-FP8 input ", name);
192	    NVTE_CHECK(!t.scale_inv.has_data(), "Scale_inv is not supported for non-FP8 input ", name);
193	    NVTE_CHECK(!t.columnwise_scale_inv.has_data(), "Scale_inv is not supported for non-FP8 input ",
194	               name);
195	  }
196	  NVTE_CHECK(t.has_data() || t.has_columnwise_data(), "Input ", name, " is not allocated!");
197	
198	  if (check_scale_inv_shapes) {
199	    CheckScaleTensorShape(t, name);
200	  }
201	}
