211	                 " (expected 1 entry, got shape=", t.amax.shape, ")");
212	    }
213	    if (t.has_data()) {
214	      NVTE_CHECK(t.scale_inv.has_data(), "FP8 scaling factor output ", name,
215	                 "_scale_inverse must be allocated");
216	      NVTE_CHECK(t.scale_inv.dtype == DType::kFloat32 || t.scale_inv.dtype == DType::kFloat8E8M0,
217	                 "FP8 scaling factor output ", name,
218	                 "_scale_inverse has invalid dtype "
219	                 "(expected Float32 or Float8E8M0, got ",
220	                 to_string(t.scale_inv.dtype), ")");
221	    }
222	    if (t.has_columnwise_data()) {
223	      NVTE_CHECK(t.columnwise_scale_inv.has_data(), "FP8 scaling factor output ", name,
224	                 "_columnwise_scale_inverse must be allocated");
225	      NVTE_CHECK(t.columnwise_scale_inv.dtype == DType::kFloat32 ||
226	                     t.columnwise_scale_inv.dtype == DType::kFloat8E8M0,
227	                 "FP8 scaling factor output ", name,
228	                 "_columnwise_scale_inverse has invalid dtype "
229	                 "(expected Float32 or Float8E8M0, got ",
230	                 to_string(t.columnwise_scale_inv.dtype), ")");
231	    }
232	  } else if (is_fp4_dtype(type)) {
233	    // FP4 output needs to have the scale_inv
234	    if (t.has_data()) {
235	      NVTE_CHECK(t.scale_inv.has_data(), "FP4 scaling factor output ", name,
236	                 "_scale_inverse must be allocated");
237	      NVTE_CHECK(t.scale_inv.dtype == DType::kFloat8E4M3, "FP4 scaling factor output ", name,
238	                 "_scale_inverse has invalid dtype "
239	                 "(expected Float8E4M3, got ",
240	                 to_string(t.scale_inv.dtype), ")");
241	    }
242	    if (t.has_columnwise_data()) {
243	      NVTE_CHECK(t.columnwise_scale_inv.has_data(), "FP4 scaling factor output ", name,
244	                 "_columnwise_scale_inverse must be allocated");
245	      NVTE_CHECK(t.columnwise_scale_inv.dtype == DType::kFloat8E4M3, "FP4 scaling factor output ",
246	                 name,
247	                 "_columnwise_scale_inverse has invalid dtype "
248	                 "(expected Float8E4M3, got ",
249	                 to_string(t.columnwise_scale_inv.dtype), ")");
250	    }
251	  } else {
252	    NVTE_CHECK(!t.scale.has_data(), "Scale is not supported for non-FP8 output ", name);
253	    NVTE_CHECK(!t.scale_inv.has_data(), "Scale_inv is not supported for non-FP8 output ", name);
254	    NVTE_CHECK(!t.columnwise_scale_inv.has_data(), "Scale_inv is not supported for non-FP8 input ",
255	               name);
256	  }
257	
258	  if (!allow_empty) {
259	    NVTE_CHECK(t.has_data() || t.has_columnwise_data(), "Output ", name, " is not allocated!");
260	  }
261	
262	  CheckScaleTensorShape(t, name);
