265	void CheckGroupedTensorShapeArrays(const GroupedTensor &t, std::string_view name) {
266	  NVTE_CHECK(t.num_tensors > 0, "Grouped tensor ", name, " has no tensors!");
267	
268	  // Helper lambda to validate shape arrays
269	  // All three arrays are OPTIONAL:
270	  // - first_dims: empty if all tensors have same first dimension
271	  // - last_dims: empty if all tensors have same last dimension
272	  // - tensor_offsets: empty if all tensors have same shape (offsets are predictable)
273	  auto check_shape_array = [&](const SimpleTensor &arr, const char *arr_name) {
274	    if (arr.has_data()) {
275	      NVTE_CHECK(arr.shape.size() == 1, "Grouped tensor ", name, " ", arr_name, " must be 1D");
276	      NVTE_CHECK(arr.dtype == DType::kInt64, "Grouped tensor ", name, " ", arr_name,
277	                 " must have dtype Int64");
278	      NVTE_CHECK(arr.shape[0] == t.num_tensors, "Grouped tensor ", name, " ", arr_name, " size (",
279	                 arr.shape[0], ") must equal num_tensors (", t.num_tensors, ")");
280	    }
281	  };
282	
283	  // Validate shape arrays (all optional)
284	  check_shape_array(t.first_dims, "first_dims");
285	  check_shape_array(t.last_dims, "last_dims");
286	
287	  // tensor_offsets uses CSR-style prefix-sum layout with num_tensors+1 entries:
288	  // offsets[i] = start of tensor i, offsets[num_tensors] = total elements
289	  if (t.tensor_offsets.has_data()) {
290	    NVTE_CHECK(t.tensor_offsets.shape.size() == 1, "Grouped tensor ", name,
291	               " tensor_offsets must be 1D");
292	    NVTE_CHECK(t.tensor_offsets.dtype == DType::kInt64, "Grouped tensor ", name,
293	               " tensor_offsets must have dtype Int64");
294	    NVTE_CHECK(t.tensor_offsets.shape[0] == t.num_tensors + 1, "Grouped tensor ", name,
295	               " tensor_offsets size (", t.tensor_offsets.shape[0], ") must equal num_tensors+1 (",
296	               t.num_tensors + 1, ")");
297	  }
298	
299	  // tensor_offsets is required if any dimension varies
300	  // (i.e., required unless all_same_shape())
301	  if (!t.all_same_shape()) {
302	    NVTE_CHECK(
303	        t.tensor_offsets.dptr != nullptr, "Grouped tensor ", name,
304	        " must have tensor_offsets when any dimension varies (first_dims or last_dims is set)");
305	  }
306	
307	  // Validate logical_shape
308	  NVTE_CHECK(t.logical_shape.ndim == 2, "Grouped tensor ", name, " logical_shape must be 2D");
309	  NVTE_CHECK(t.logical_shape.data[0] > 0 && t.logical_shape.data[1] > 0, "Grouped tensor ", name,
310	             " logical_shape must have positive dimensions");
311	
312	  // Validate all data fields are 1D (flattened)
313	  if (t.has_data()) {
314	    NVTE_CHECK(t.data.shape.size() == 1, "Grouped tensor ", name, " data must be 1D");
315	  }
316	  if (t.has_columnwise_data()) {
317	    NVTE_CHECK(t.columnwise_data.shape.size() == 1, "Grouped tensor ", name,
318	               " columnwise_data must be 1D");
319	  }
320	
321	  // Validate data size matches logical_shape
322	  size_t expected_numel = t.logical_shape.data[0] * t.logical_shape.data[1];
323	  if (t.has_data()) {
324	    NVTE_CHECK(t.data.numel() == expected_numel, "Grouped tensor ", name, " data size (",
325	               t.data.numel(), ") must match logical_shape size (", expected_numel, ")");
326	  }
327	  if (t.has_columnwise_data()) {
328	    NVTE_CHECK(t.columnwise_data.numel() == expected_numel, "Grouped tensor ", name,
329	               " columnwise_data size (", t.columnwise_data.numel(),
330	               ") must match logical_shape size (", expected_numel, ")");
331	  }
332	}
