334	// Helper function to check scale_inv for both input and output
335	static void CheckGroupedScaleInv(const GroupedTensor &t, std::string_view name, bool is_output) {
336	  const char *tensor_type = is_output ? "output" : "input";
337	
338	  // Helper to check scale_inv for both rowwise and columnwise layouts
339	  auto check_scales = [&](DType expected_dtype) {
340	    if (t.has_data()) {
341	      NVTE_CHECK(t.scale_inv.has_data(), tensor_type, " ", name,
342	                 " rowwise scale_inv must be allocated");
343	      NVTE_CHECK(t.scale_inv.dtype == expected_dtype, tensor_type, " ", name,
344	                 " rowwise scale_inv has invalid dtype (expected ", to_string(expected_dtype),
345	                 ", got ", to_string(t.scale_inv.dtype), ")");
346	    }
347	    if (t.has_columnwise_data()) {
348	      NVTE_CHECK(t.columnwise_scale_inv.has_data(), tensor_type, " ", name,
349	                 " columnwise scale_inv must be allocated");
350	      NVTE_CHECK(t.columnwise_scale_inv.dtype == expected_dtype, tensor_type, " ", name,
351	                 " columnwise scale_inv has invalid dtype (expected ", to_string(expected_dtype),
352	                 ", got ", to_string(t.columnwise_scale_inv.dtype), ")");
353	    }
354	  };
355	
356	  // Determine expected dtype based on data type and scaling mode
357	  if (is_fp8_dtype(t.dtype()) && is_tensor_scaling(t.scaling_mode)) {
358	    check_scales(DType::kFloat32);
359	  } else if (is_fp8_block_scaling(t.scaling_mode)) {
360	    check_scales(DType::kFloat32);
361	  } else if (is_mxfp8_scaling(t.scaling_mode)) {
362	    check_scales(DType::kFloat8E8M0);
363	  } else if (is_nvfp4_scaling(t.scaling_mode)) {
364	    check_scales(DType::kFloat8E4M3);
365	  } else {
366	    // Non-quantized types should not have scale/scale_inv
367	    NVTE_CHECK(!t.scale_inv.has_data(), "Scale_inv not supported for non-quantized ", tensor_type,
368	               " ", name);
369	    NVTE_CHECK(!t.columnwise_scale_inv.has_data(), "Scale_inv not supported for non-quantized ",
370	               tensor_type, " ", name);
371	  }
372	}
