375	  NVTE_CHECK(t.has_data() || t.has_columnwise_data(), "Input grouped tensor ", name,
376	             " not allocated");
377	  CheckGroupedScaleInv(t, name, false);
378	  CheckGroupedTensorShapeArrays(t, name);
