380	
381	void CheckOutputGroupedTensor(const GroupedTensor &t, std::string_view name, bool allow_empty) {
382	  if (!allow_empty) {
383	    NVTE_CHECK(t.has_data() || t.has_columnwise_data(), "Output grouped tensor ", name,
384	               " not allocated");
385	  }
386	
387	  // Only perform dtype-specific validation if data is allocated
388	  if (t.has_data() || t.has_columnwise_data()) {
389	    // Amax validation for delayed scaling
390	    if (is_fp8_dtype(t.dtype()) && t.scaling_mode == NVTE_DELAYED_TENSOR_SCALING) {
391	      NVTE_CHECK(t.amax.has_data(), "Output ", name, " amax must be allocated");
392	      NVTE_CHECK(t.amax.dtype == DType::kFloat32, "Output ", name, " amax must be Float32");
393	    }
394	    CheckGroupedScaleInv(t, name, true);
395	  }
396	
397	  CheckGroupedTensorShapeArrays(t, name);
398	}
