402	constexpr size_t kDefaultTensorHandlePoolSizeMB = 20;
403	constexpr size_t kBytesPerMB = 1024 * 1024;
404	
405	size_t GetTensorHandlePoolSizeMB(const char *env_var) {
406	  const char *env_value = std::getenv(env_var);
407	  if (env_value == nullptr || env_value[0] == '\0') {
408	    return kDefaultTensorHandlePoolSizeMB;
409	  }
410	
411	  const std::string value(env_value);
412	  constexpr const char *kWhitespace = " \t\n\r\f\v";
413	  const size_t first = value.find_first_not_of(kWhitespace);
414	  const size_t last = value.find_last_not_of(kWhitespace);
415	  NVTE_CHECK(first != std::string::npos, env_var, " must be a positive integer.");
416	
417	  const char *begin = value.c_str() + first;
418	  const char *expected_end = value.c_str() + last + 1;
419	  errno = 0;
420	  char *end = nullptr;
421	  const uint64_t pool_size_mb = std::strtoul(begin, &end, 10);
422	
423	  NVTE_CHECK(value[first] >= '0' && value[first] <= '9' && end == expected_end && pool_size_mb > 0,
424	             env_var, " must be a positive integer, got \"", value, "\".");
425	  NVTE_CHECK(errno != ERANGE, env_var, " is too large.");
426	  NVTE_CHECK(pool_size_mb <= std::numeric_limits<size_t>::max() / kBytesPerMB, env_var,
427	             " is too large.");
428	  return static_cast<size_t>(pool_size_mb);
429	}
