431	size_t GetTensorHandlePoolCapacity(size_t pool_size_mb, size_t handle_size, const char *handle_name,
432	                                   const char *env_var) {
433	  const size_t pool_size_bytes = pool_size_mb * kBytesPerMB;
434	  NVTE_CHECK(pool_size_bytes >= handle_size, env_var, "=", pool_size_mb,
435	             " MiB is too small for one ", handle_name, " handle of size ", handle_size, " bytes.");
436	  return pool_size_bytes / handle_size;
437	}
