441	class TensorAllocator {
442	 public:
443	  static TensorAllocator &instance() {
444	    static TensorAllocator allocator;
445	    return allocator;
446	  }
447	
448	  ~TensorAllocator() {}
449	
450	  void Allocate(NVTEScalingMode mode, NVTETensor *out, size_t N) {
451	    std::lock_guard<std::mutex> lock(mutex);
452	    const size_t available = free_list.size() + (memory.capacity() - memory.size());
453	    NVTE_CHECK(available >= N, "Cannot allocate ", N,
454	               " new NVTETensors. Maximum number of tensors reached: ", MAX_TENSOR_NUM, " (",
455	               TENSOR_HANDLE_POOL_SIZE_MB,
456	               " MiB handle pool). If your application legitimately needs more tensor handles, "
457	               "increase NVTE_TENSOR_HANDLE_POOL_SIZE_MB.");
458	    for (size_t i = 0; i < N; ++i) {
459	      uintptr_t index;
460	      if (!free_list.empty()) {
461	        index = free_list.back();
462	        free_list.pop_back();
463	      } else {
464	        memory.emplace_back();
465	        index = memory.size();
466	        size = index;
467	        memory[index - 1].nvte_tensor = reinterpret_cast<NVTETensor>(index);
468	      }
469	      memory[index - 1].scaling_mode = mode;
470	      out[i] = reinterpret_cast<NVTETensor>(index);
471	    }
472	    if (debug) {
473	      std::cout << "Allocated range of " << N << " tensors. Free list size: " << free_list.size()
474	                << " and capacity " << free_list.capacity() << std::endl;
475	    }
476	  }
477	
478	  NVTETensor Allocate(NVTEScalingMode mode) {
479	    NVTETensor t;
480	    Allocate(mode, &t, 1);
481	    return t;
482	  }
483	
484	  void Free(NVTETensor *t, size_t N) {
485	    std::lock_guard<std::mutex> lock(mutex);
486	    for (size_t i = 0; i < N; ++i) {
487	      uintptr_t index = reinterpret_cast<uintptr_t>(t[i]);
488	      if (index == 0) continue;
489	      NVTE_CHECK(index <= memory.size(), "Invalid tensor.");
490	      free_list.push_back(index);
491	      // Clean up
492	      memory[index - 1].clear();
493	    }
494	    if (debug) {
495	      std::cout << "Freed range of " << N << " tensors. Free list size: " << free_list.size()
496	                << " and capacity " << free_list.capacity() << std::endl;
497	    }
498	  }
499	
500	  void Free(NVTETensor t) {
501	    if (reinterpret_cast<uintptr_t>(t) == 0) return;
502	    Free(&t, 1);
503	  }
504	
505	  Tensor *convertNVTETensor(NVTETensor t) {
506	    uintptr_t index = reinterpret_cast<uintptr_t>(t);
507	    // 1-based indexing to enable 0-initialization of NVTETensor
508	    // to be invalid tensor
509	    static_assert(nullptr == 0);
510	    if (index != 0 && index <= size) {
511	      return &(memory[index - 1]);
512	    }
513	    return nullptr;
514	  }
515	
516	  void setDebug(bool debug) {
517	    std::lock_guard<std::mutex> lock(mutex);
518	    this->debug = debug;
519	  }
520	
521	 private:
522	  TensorAllocator() {
523	    std::lock_guard<std::mutex> lock(mutex);
524	    memory.reserve(MAX_TENSOR_NUM);
525	  }
526	
527	  std::mutex mutex;
528	  std::atomic<size_t> size;
529	  // Should be replaced by virtual memory allocation
530	  const size_t TENSOR_HANDLE_POOL_SIZE_MB =
531	      GetTensorHandlePoolSizeMB("NVTE_TENSOR_HANDLE_POOL_SIZE_MB");
532	  const size_t MAX_TENSOR_NUM = GetTensorHandlePoolCapacity(
533	      TENSOR_HANDLE_POOL_SIZE_MB, sizeof(Tensor), "NVTETensor", "NVTE_TENSOR_HANDLE_POOL_SIZE_MB");
534	  std::vector<uintptr_t> free_list;
535	  std::vector<Tensor> memory;
536	  bool debug = false;
537	};
538	
539	Tensor *convertNVTETensor(const NVTETensor t) {
540	  return TensorAllocator::instance().convertNVTETensor(t);
541	}
