543	Tensor *convertNVTETensorCheck(const NVTETensor t) {
544	  Tensor *ptr = TensorAllocator::instance().convertNVTETensor(t);
545	  NVTE_CHECK(ptr != nullptr, "Invalid tensor.");
546	  return ptr;
547	}
