549	// GroupedTensor allocator - similar pattern to TensorAllocator
550	class GroupedTensorAllocator {
551	 public:
552	  static GroupedTensorAllocator &instance() {
553	    static GroupedTensorAllocator allocator;
554	    return allocator;
555	  }
556	
557	  ~GroupedTensorAllocator() {}
558	
559	  NVTEGroupedTensor Allocate(NVTEScalingMode mode, size_t num_tensors, NVTEShape logical_shape) {
560	    std::lock_guard<std::mutex> lock(mutex);
561	    if (!free_list.empty()) {
562	      uintptr_t index = free_list.back();
563	      NVTEGroupedTensor ret = reinterpret_cast<NVTEGroupedTensor>(index);
564	      free_list.pop_back();
565	      // 1-based indexing - fully reinitialize the tensor to avoid stale data
566	      memory[index - 1].scaling_mode = mode;
567	      memory[index - 1].num_tensors = num_tensors;
568	      memory[index - 1].logical_shape = logical_shape;
569	      memory[index - 1].nvte_tensor = ret;
570	      return ret;
571	    }
572	    if (memory.size() < memory.capacity()) {
573	      memory.emplace_back(mode, num_tensors);
574	      GroupedTensor &t = memory.back();
575	      size = memory.size();
576	      // 1-based indexing
577	      uintptr_t index = memory.size();
578	      t.logical_shape = logical_shape;
579	      t.nvte_tensor = reinterpret_cast<NVTEGroupedTensor>(index);
580	      return reinterpret_cast<NVTEGroupedTensor>(index);
581	    }
582	    NVTE_ERROR(
583	        "Cannot allocate a new NVTEGroupedTensor. Maximum number of grouped tensors reached: ",
584	        MAX_GROUPED_TENSOR_NUM, " (", GROUPED_TENSOR_HANDLE_POOL_SIZE_MB,
585	        " MiB handle pool). If your application legitimately needs more grouped tensor handles, "
586	        "increase NVTE_GROUPED_TENSOR_HANDLE_POOL_SIZE_MB.");
587	  }
588	
589	  void Free(NVTEGroupedTensor t) {
590	    uintptr_t index = reinterpret_cast<uintptr_t>(t);
591	    if (index == 0) return;
592	    std::lock_guard<std::mutex> lock(mutex);
593	    NVTE_CHECK(index <= memory.size(), "Invalid grouped tensor.");
594	    free_list.push_back(index);
595	    // Clean up
596	    memory[index - 1].clear();
597	  }
598	
599	  GroupedTensor *convertNVTEGroupedTensor(NVTEGroupedTensor t) {
600	    uintptr_t index = reinterpret_cast<uintptr_t>(t);
601	    // 1-based indexing to enable 0-initialization of NVTEGroupedTensor
602	    // to be invalid tensor
603	    static_assert(nullptr == 0);
604	    if (index != 0 && index <= size) {
605	      return &(memory[index - 1]);
606	    }
607	    return nullptr;
608	  }
609	
610	 private:
611	  GroupedTensorAllocator() {
612	    std::lock_guard<std::mutex> lock(mutex);
613	    memory.reserve(MAX_GROUPED_TENSOR_NUM);
614	  }
615	
616	  std::mutex mutex;
617	  std::atomic<size_t> size;
618	  const size_t GROUPED_TENSOR_HANDLE_POOL_SIZE_MB =
619	      GetTensorHandlePoolSizeMB("NVTE_GROUPED_TENSOR_HANDLE_POOL_SIZE_MB");
620	  const size_t MAX_GROUPED_TENSOR_NUM =
621	      GetTensorHandlePoolCapacity(GROUPED_TENSOR_HANDLE_POOL_SIZE_MB, sizeof(GroupedTensor),
622	                                  "NVTEGroupedTensor", "NVTE_GROUPED_TENSOR_HANDLE_POOL_SIZE_MB");
623	  std::vector<uintptr_t> free_list;
624	  std::vector<GroupedTensor> memory;
625	};
