841	void nvte_set_tensor_param_v2(NVTETensor tensor, NVTETensorParam param, const void *buf,
842	                              size_t size_in_bytes) {
843	  // Check attribute and buffer
844	  NVTE_CHECK(param < kNVTENumTensorParams, "Invalid NVTETensorParam (got ", static_cast<int>(param),
845	             ")");
846	  NVTE_CHECK(tensor != nullptr, "Tensor pointer can't be NULL.");
847	  auto &t = *transformer_engine::convertNVTETensorCheck(tensor);
848	  const auto &attr_size = transformer_engine::Tensor::attr_sizes[param];
849	  NVTE_CHECK(size_in_bytes >= attr_size,
850	             "Buffer is too small for tensor parameter "
851	             "(parameter ",
852	             static_cast<int>(param), " needs ", attr_size, " bytes, but buffer has ",
853	             size_in_bytes, " bytes)");
854	  NVTE_CHECK(buf != nullptr, "Invalid buffer (got NULL)");
855	
856	  // Read from buffer
857	  switch (param) {
858	    case kNVTERowwiseData: {
859	      const NVTEBasicTensor *basic_tensor = reinterpret_cast<const NVTEBasicTensor *>(buf);
860	      t.data = *basic_tensor;
861	      break;
862	    }
863	    case kNVTEColumnwiseData: {
864	      const NVTEBasicTensor *basic_tensor = reinterpret_cast<const NVTEBasicTensor *>(buf);
865	      t.columnwise_data = *basic_tensor;
866	      break;
867	    }
868	    case kNVTEScale: {
869	      const NVTEBasicTensor *basic_tensor = reinterpret_cast<const NVTEBasicTensor *>(buf);
870	      t.scale = *basic_tensor;
871	      break;
872	    }
873	    case kNVTEAmax: {
874	      const NVTEBasicTensor *basic_tensor = reinterpret_cast<const NVTEBasicTensor *>(buf);
875	      t.amax = *basic_tensor;
876	      break;
877	    }
878	    case kNVTERowwiseScaleInv: {
879	      const NVTEBasicTensor *basic_tensor = reinterpret_cast<const NVTEBasicTensor *>(buf);
880	      t.scale_inv = *basic_tensor;
881	      break;
882	    }
883	    case kNVTEColumnwiseScaleInv: {
884	      const NVTEBasicTensor *basic_tensor = reinterpret_cast<const NVTEBasicTensor *>(buf);
885	      t.columnwise_scale_inv = *basic_tensor;
886	      break;
887	    }
888	    case kNVTEColumnwiseAmax: {
889	      const NVTEBasicTensor *basic_tensor = reinterpret_cast<const NVTEBasicTensor *>(buf);
890	      t.columnwise_amax = *basic_tensor;
891	      break;
892	    }
893	    case kNVTEWithGEMMSwizzledScales:
894	      t.with_gemm_swizzled_scales = static_cast<bool>(*reinterpret_cast<const uint8_t *>(buf));
895	      break;
896	    case kNVTERowScaledNVFP4:
897	      t.row_scaled_nvfp4 = static_cast<bool>(*reinterpret_cast<const uint8_t *>(buf));
898	      break;
899	    case kNVTENVFP4E4M3Max:
900	      std::memcpy(&t.nvfp4_e4m3_max, buf, attr_size);
901	      NVTE_CHECK(t.nvfp4_e4m3_max == 448 || t.nvfp4_e4m3_max == 256,
902	                 "Unsupported NVFP4 E4M3 max (got ", t.nvfp4_e4m3_max, ")");
903	      break;
904	    default:
905	      NVTE_ERROR("Unsupported tensor parameter (", static_cast<int>(param), ")");
906	  }
907	}
