909	void nvte_get_tensor_param_v2(const NVTETensor tensor, NVTETensorParam param, void *buf,
910	                              size_t size_in_bytes, size_t *size_written) {
911	  using namespace transformer_engine;
912	
913	  // Check param
914	  NVTE_CHECK(param < kNVTENumTensorParams, "Invalid NVTETensorParam (got ", static_cast<int>(param),
915	             ")");
916	
917	  // Write attribute size if provided
918	  const auto &attr_size = Tensor::attr_sizes[param];
919	  if (size_written != nullptr) {
920	    *size_written = attr_size;
921	  }
922	
923	  // Return immediately if buffer is not provided
924	  if (buf == nullptr) {
925	    return;
926	  }
927	
928	  // Check buffer size
929	  NVTE_CHECK(size_in_bytes >= attr_size,
930	             "Buffer is too small for tensor parameter "
931	             "(parameter ",
932	             static_cast<int>(param), " needs ", attr_size, " bytes, but buffer has ",
933	             size_in_bytes, " bytes)");
934	
935	  // Get C++ tensor
936	  const Tensor *t = convertNVTETensor(tensor);
937	  std::optional<Tensor> dummy;
938	  if (t == nullptr) {
939	    // Make dummy tensor if provided tensor is invalid
940	    dummy.emplace();
941	    t = &(*dummy);
942	  }
943	
944	  // Write to buffer
945	  switch (param) {
946	    case kNVTERowwiseData: {
947	      NVTEBasicTensor *basic_tensor = reinterpret_cast<NVTEBasicTensor *>(buf);
948	      *basic_tensor = static_cast<NVTEBasicTensor>(t->data);
949	      break;
950	    }
951	    case kNVTEColumnwiseData: {
952	      NVTEBasicTensor *basic_tensor = reinterpret_cast<NVTEBasicTensor *>(buf);
953	      *basic_tensor = static_cast<NVTEBasicTensor>(t->columnwise_data);
954	      break;
955	    }
956	    case kNVTEScale: {
957	      NVTEBasicTensor *basic_tensor = reinterpret_cast<NVTEBasicTensor *>(buf);
958	      *basic_tensor = static_cast<NVTEBasicTensor>(t->scale);
959	      break;
960	    }
961	    case kNVTEAmax: {
962	      NVTEBasicTensor *basic_tensor = reinterpret_cast<NVTEBasicTensor *>(buf);
963	      *basic_tensor = static_cast<NVTEBasicTensor>(t->amax);
964	      break;
965	    }
966	    case kNVTERowwiseScaleInv: {
967	      NVTEBasicTensor *basic_tensor = reinterpret_cast<NVTEBasicTensor *>(buf);
968	      *basic_tensor = static_cast<NVTEBasicTensor>(t->scale_inv);
969	      break;
970	    }
971	    case kNVTEColumnwiseScaleInv: {
972	      NVTEBasicTensor *basic_tensor = reinterpret_cast<NVTEBasicTensor *>(buf);
973	      *basic_tensor = static_cast<NVTEBasicTensor>(t->columnwise_scale_inv);
974	      break;
975	    }
976	    case kNVTEColumnwiseAmax: {
977	      NVTEBasicTensor *basic_tensor = reinterpret_cast<NVTEBasicTensor *>(buf);
978	      *basic_tensor = static_cast<NVTEBasicTensor>(t->columnwise_amax);
979	      break;
980	    }
981	    case kNVTEWithGEMMSwizzledScales:
982	      *reinterpret_cast<uint8_t *>(buf) = static_cast<uint8_t>(t->with_gemm_swizzled_scales);
983	      break;
984	    case kNVTERowScaledNVFP4:
985	      *reinterpret_cast<uint8_t *>(buf) = static_cast<uint8_t>(t->row_scaled_nvfp4);
986	      break;
987	    case kNVTENVFP4E4M3Max:
988	      std::memcpy(buf, &t->nvfp4_e4m3_max, attr_size);
989	      break;
990	    default:
991	      NVTE_ERROR("Unsupported tensor parameter (", static_cast<int>(param), ")");
992	  }
