1012	void nvte_zero_tensor(const NVTETensor tensor, cudaStream_t stream) {
1013	  if (tensor == nullptr) return;
1014	  const auto &t = *transformer_engine::convertNVTETensorCheck(tensor);
1015	
1016	  // Zero out tensor data if allocated
1017	  if (t.data.dptr != nullptr) {
1018	    const auto size = t.data.buffer_size_bytes();
1019	    if (size > 0) {
1020	      NVTE_CHECK_CUDA(cudaMemsetAsync(t.data.dptr, 0, size, stream));
1021	    }
1022	  }
1023	
1024	  // Zero out amax if allocated
1025	  if (t.amax.dptr != nullptr) {
1026	    const auto size = t.amax.buffer_size_bytes();
1027	    if (size > 0) {
1028	      NVTE_CHECK_CUDA(cudaMemsetAsync(t.amax.dptr, 0, size, stream));
1029	    }
1030	  }
