1037	void nvte_get_quantization_config_attribute(NVTEQuantizationConfig config,
1038	                                            NVTEQuantizationConfigAttribute attr, void *buf,
1039	                                            size_t size_in_bytes, size_t *size_written) {
1040	  using namespace transformer_engine;
1041	
1042	  // Write attribute size
1043	  NVTE_CHECK(attr < kNVTEQuantizationConfigNumAttributes,
1044	             "Invalid NVTEQuantizationConfigAttribute (got ", static_cast<int>(attr), ")");
1045	  const auto &attr_size = QuantizationConfig::attr_sizes[attr];
1046	  if (size_written != nullptr) {
1047	    *size_written = attr_size;
1048	  }
1049	
1050	  // Return immediately if buffer is not provided
1051	  if (buf == nullptr) {
1052	    return;
1053	  }
1054	
1055	  // Check buffer size
1056	  NVTE_CHECK(size_in_bytes >= attr_size,
1057	             "Buffer is too small for quantization config attribute "
1058	             "(attribute ",
1059	             static_cast<int>(attr), " needs ", attr_size, " bytes, but buffer has ", size_in_bytes,
1060	             " bytes)");
1061	
1062	  // bool size is implementation-dependent, so we explicitly specify
1063	  // uint8_t in the user-facing API.
1064	  auto bool_to_uint8 = [](bool in, void *out) {
1065	    *reinterpret_cast<uint8_t *>(out) = static_cast<uint8_t>(in);
1066	  };
1067	
1068	  // Write to buffer
1069	  NVTE_CHECK(config != nullptr, "Invalid NVTEQuantizationConfig (got NULL)");
1070	  const auto &config_ = *reinterpret_cast<const QuantizationConfig *>(config);
1071	  switch (attr) {
1072	    case kNVTEQuantizationConfigForcePow2Scales:
1073	      bool_to_uint8(config_.force_pow_2_scales, buf);
1074	      break;
1075	    case kNVTEQuantizationConfigAmaxEpsilon:
1076	      std::memcpy(buf, &config_.amax_epsilon, attr_size);
1077	      break;
1078	    case kNVTEQuantizationConfigNoopTensor:
1079	      std::memcpy(buf, &config_.noop_tensor, attr_size);
1080	      break;
1081	    case kNVTEQuantizationConfigFloat8BlockScaleTensorFormat: {
1082	      // Deprecated
1083	      const auto invalid = Float8BlockScaleTensorFormat::INVALID;
1084	      std::memcpy(buf, &invalid, attr_size);
1085	      break;
1086	    }
1087	    case kNVTEQuantizationConfigRNGState:
1088	      std::memcpy(buf, &config_.rng_state, attr_size);
1089	      break;
1090	    case kNVTEQuantizationConfigNVFP42DQuantization:
1091	      bool_to_uint8(config_.nvfp4_2d_quantization, buf);
1092	      break;
1093	    case kNVTEQuantizationConfigStochasticRounding:
1094	      bool_to_uint8(config_.stochastic_rounding, buf);
1095	      break;
1096	    case kNVTEQuantizationConfigUseFastMath:
1097	      bool_to_uint8(config_.use_fast_math, buf);
1098	      break;
1099	    case kNVTEQuantizationConfigNVFP44Over6Mode: {
1100	      const auto val = static_cast<uint8_t>(config_.nvfp4_4over6_mode);
1101	      std::memcpy(buf, &val, attr_size);
1102	      break;
1103	    }
1104	    case kNVTEQuantizationConfigNVFP44Over6ErrUseFastMath:
1105	      bool_to_uint8(config_.nvfp4_4over6_err_use_fast_math, buf);
1106	      break;
1107	    case kNVTEQuantizationConfigMXFP82DQuantization:
1108	      bool_to_uint8(config_.mxfp8_2d_quantization, buf);
1109	      break;
1110	    default:
1111	      NVTE_ERROR("Unsupported NVTEQuantizationConfigAttribute (got ", static_cast<int>(attr), ")");
1112	  }
1113	}
