35	inline float *GetScalarOne() {
36	  static std::once_flag init_flag;
37	  std::call_once(init_flag, []() {
38	    float one = 1.0f;
39	    NVTE_CHECK_CUDA(cudaMemcpyToSymbol(one_device, &one, sizeof(float)));
40	  });
41	  // return address by cudaGetSymbolAddress
42	  float *dev_ptr;
43	  NVTE_CHECK_CUDA(cudaGetSymbolAddress(reinterpret_cast<void **>(&dev_ptr), one_device));
44	  return dev_ptr;
45	}
