47	inline float *GetScalarZero() {
48	  static std::once_flag init_flag;
49	  std::call_once(init_flag, []() {
50	    float zero = 0.0f;
51	    NVTE_CHECK_CUDA(cudaMemcpyToSymbol(zero_device, &zero, sizeof(float)));
52	  });
53	  // return address by cudaGetSymbolAddress
54	  float *dev_ptr;
55	  NVTE_CHECK_CUDA(cudaGetSymbolAddress(reinterpret_cast<void **>(&dev_ptr), zero_device));
