75	/* Parameters for cuBLAS GEMM
76	 *
77	 * cuBLAS follows the BLAS convention of column-major ordering. This
78	 * is different than the row-major that is typically used in
79	 * Transformer Engine.
80	 *
81	 */
82	struct GemmParam {
83	  void *A = nullptr;
84	  void *B = nullptr;
85	  cublasOperation_t transA = CUBLAS_OP_N;
86	  cublasOperation_t transB = CUBLAS_OP_N;
87	  transformer_engine::DType Atype = transformer_engine::DType::kNumTypes;
88	  transformer_engine::DType Btype = transformer_engine::DType::kNumTypes;
89	  void *A_scale_inv = nullptr;
90	  void *B_scale_inv = nullptr;
91	  int lda = 0;  // A column strides
92	  int ldb = 0;  // B column strides
93	};
94	
95	/* Populate parameters for cuBLAS GEMM
96	 *
97	 * cuBLAS follows the BLAS convention of column-major ordering. This
98	 * is different than the row-major that is typically used in
99	 * Transformer Engine.
100	 *
101	 */
102	GemmParam CanonicalizeGemmInput(const transformer_engine::Tensor &A, const cublasOperation_t transA,
103	                                const transformer_engine::Tensor &B, const cublasOperation_t transB,
104	                                int m, int n, int k) {
105	  using namespace transformer_engine;
106	  NVTE_CHECK(
107	      A.scaling_mode == B.scaling_mode ||
108	          (A.scaling_mode == NVTE_BLOCK_SCALING_1D && B.scaling_mode == NVTE_BLOCK_SCALING_2D) ||
109	          (A.scaling_mode == NVTE_BLOCK_SCALING_2D && B.scaling_mode == NVTE_BLOCK_SCALING_1D),
110	      "Inputs A and B to GEMM need to have compatible scaling modes, but got A.scaling_mode = " +
111	          to_string(A.scaling_mode) + ", B.scaling_mode = " + to_string(B.scaling_mode));
112	  NVTE_CHECK(A.has_data() || A.has_columnwise_data(), "Input A does not hold any data!");
113	  NVTE_CHECK(B.has_data() || B.has_columnwise_data(), "Input B does not hold any data!");
114	  GemmParam ret;
115	
116	  // Transpose mode with column-major ordering
117	  bool is_A_transposed = transA == CUBLAS_OP_T;
118	  bool is_B_transposed = transB == CUBLAS_OP_T;
119	
120	  // Set conditions for MXFP8 and NVFP4 gemm execution.
121	  const auto nvfp4 = is_nvfp_scaling(A.scaling_mode) && is_nvfp_scaling(B.scaling_mode);
122	  const auto mxfp8 = !nvfp4 && is_mxfp_scaling(A.scaling_mode) && is_mxfp_scaling(B.scaling_mode);
123	  int is_nvte_non_tn_fp8_gemm_supported = 0;  // needed only for per tensor scaling
124	  if (is_tensor_scaling(A.scaling_mode) || is_tensor_scaling(B.scaling_mode)) {
125	    is_nvte_non_tn_fp8_gemm_supported = nvte_is_non_tn_fp8_gemm_supported();
126	  }
127	
128	  // Configure A matrix
129	  if (is_tensor_scaling(A.scaling_mode)) {
130	    // Unscaled or FP8 tensor scaling
131	    ret.A = A.data.dptr;
132	    ret.transA = transA;
133	    ret.Atype = A.data.dtype;
134	    ret.A_scale_inv = A.scale_inv.dptr;
135	    ret.lda = is_A_transposed ? k : m;
136	    if (!is_nvte_non_tn_fp8_gemm_supported && !is_A_transposed) {
137	      // Hopper only supports TN GEMMs for FP8. "Column-wise data" is transpose of data.
138	      if (A.has_columnwise_data() && is_fp8_dtype(A.columnwise_data.dtype)) {
139	        ret.A = A.columnwise_data.dptr;
140	        ret.transA = CUBLAS_OP_T;
141	        ret.Atype = A.columnwise_data.dtype;
142	        ret.A_scale_inv = A.columnwise_scale_inv.dptr;
143	        ret.lda = k;
144	      } else {
145	        NVTE_CHECK(!is_fp8_dtype(ret.Atype), "Input A is missing column-wise usage");
146	      }
147	    } else if (is_nvte_non_tn_fp8_gemm_supported && !A.has_data()) {
148	      // Blackwell supports any GEMM layout for FP8, so we can use column-wise/transposed
149	      // data  with the mirrored transpose-flag if we don't have row-wise data.
150	      NVTE_CHECK(A.has_columnwise_data() && is_fp8_dtype(A.columnwise_data.dtype),
151	                 "Input A is missing column-wise usage");
152	      ret.A = A.columnwise_data.dptr;
153	      ret.transA = is_A_transposed ? CUBLAS_OP_N : CUBLAS_OP_T;
154	      ret.Atype = A.columnwise_data.dtype;
155	      ret.A_scale_inv = A.columnwise_scale_inv.dptr;
156	      ret.lda = is_A_transposed ? m : k;
157	    }
158	
159	    if (is_fp8_dtype(ret.Atype)) {
160	      // Requirements from https://docs.nvidia.com/cuda/cublas/#tensor-core-usage
161	      NVTE_CHECK(ret.lda % 16 == 0,
162	                 "Leading dimension requirement on A for FP8 GEMM. Caller must pad.");
163	    }
164	  } else if (nvfp4) {
165	    // NVFP4 GEMM. Either the pure NVFP4 recipe or the FWD pass of the Hybrid NVFP4/MXFP8 recipe.
166	
167	    if (is_A_transposed) {
168	      NVTE_CHECK(A.has_data(), "Input A is missing row-wise usage");
169	    } else {
170	      NVTE_CHECK(is_nvfp4_scaling(A.scaling_mode),
171	                 "Input A has unsupported combination of recipe and layout");
172	      NVTE_CHECK(A.has_columnwise_data(), "Input A is missing column-wise usage");
173	    }
174	    ret.A = is_A_transposed ? A.data.dptr : A.columnwise_data.dptr;
175	    ret.transA = CUBLAS_OP_T;  // NVFP4 gemm is only supported in TN layout.
176	    ret.Atype = is_A_transposed ? A.data.dtype : A.columnwise_data.dtype;
177	    ret.A_scale_inv = is_A_transposed ? A.scale_inv.dptr : A.columnwise_scale_inv.dptr;
178	    ret.lda = k;
179	  } else if (mxfp8) {
180	    // MXFP8 GEMM. Either for pure MXFP8 recipe or backward of Hybrid NVFP4 recipe.
181	    // Note: Row-wise and column-wise data are scaled along different
182	    // dimensions (with matrix interpreted in row-major order).
183	
184	    if (is_A_transposed) {
185	      NVTE_CHECK(A.has_data(), "Input A is missing row-wise usage");
186	    } else {
187	      NVTE_CHECK(A.has_columnwise_data(), "Input A is missing column-wise usage");
188	    }
189	    ret.A = is_A_transposed ? A.data.dptr : A.columnwise_data.dptr;
190	    ret.transA = transA;
191	    ret.Atype = is_A_transposed ? A.data.dtype : A.columnwise_data.dtype;
192	    ret.A_scale_inv = is_A_transposed ? A.scale_inv.dptr : A.columnwise_scale_inv.dptr;
193	    ret.lda = is_A_transposed ? k : m;
194	  } else if (A.scaling_mode == NVTE_BLOCK_SCALING_1D || A.scaling_mode == NVTE_BLOCK_SCALING_2D) {
195	    // FP8 block scaling
196	    // Note: Hopper only supports TN GEMMs for FP8. "Column-wise data" is transpose of data.
197	    if (is_A_transposed) {
198	      NVTE_CHECK(A.has_data(), "Input A is missing row-wise usage");
199	    } else {
200	      NVTE_CHECK(A.has_columnwise_data(), "Input A is missing column-wise usage");
201	    }
202	    ret.A = is_A_transposed ? A.data.dptr : A.columnwise_data.dptr;
203	    ret.transA = CUBLAS_OP_T;
204	    ret.Atype = is_A_transposed ? A.data.dtype : A.columnwise_data.dtype;
205	    ret.A_scale_inv = is_A_transposed ? A.scale_inv.dptr : A.columnwise_scale_inv.dptr;
206	    ret.lda = k;
207	
208	    // Requirements from https://docs.nvidia.com/cuda/cublas/#tensor-core-usage
209	    NVTE_CHECK((ret.lda % 16) == 0,
210	               "Leading dimension requirement on NVTE_BLOCK_SCALING GEMM. Caller must pad.");
211	    // Divisibility of 8 derived from FP8 (m * CTypeSize) % 16 == 0 requirement.
212	    // Smallest supported CType is 2 bytes in this scaling mode.
213	    NVTE_CHECK((m % 8) == 0,
214	               "Outer dimension requirement on A for NVTE_BLOCK_SCALING GEMM. Caller must pad.");
215	  } else {
216	    NVTE_ERROR("A has unsupported scaling mode");
217	  }
218	
219	  // Configure B matrix
220	  if (is_tensor_scaling(B.scaling_mode)) {
221	    // Unscaled or FP8 tensor scaling
222	    ret.B = B.data.dptr;
223	    ret.transB = transB;
224	    ret.Btype = B.data.dtype;
225	    ret.B_scale_inv = B.scale_inv.dptr;
226	    ret.ldb = is_B_transposed ? n : k;
227	    if (!is_nvte_non_tn_fp8_gemm_supported && is_B_transposed) {
228	      // Hopper only supports TN GEMMs for FP8. "Column-wise data" is transpose of data.
229	      if (B.has_columnwise_data() && is_fp8_dtype(B.columnwise_data.dtype)) {
230	        ret.B = B.columnwise_data.dptr;
231	        ret.transB = CUBLAS_OP_N;
232	        ret.Btype = B.columnwise_data.dtype;
233	        ret.B_scale_inv = B.columnwise_scale_inv.dptr;
234	        ret.ldb = k;
235	      } else {
236	        NVTE_CHECK(!is_fp8_dtype(ret.Btype), "Input B is missing column-wise usage");
237	      }
238	    } else if (is_nvte_non_tn_fp8_gemm_supported && !B.has_data()) {
239	      // Blackwell supports any GEMM layout for FP8, so we can use column-wise/transposed
240	      // data with the mirrored transpose-flag if we don't have row-wise data.
241	      NVTE_CHECK(B.has_columnwise_data() && is_fp8_dtype(B.columnwise_data.dtype),
242	                 "Input B is missing column-wise usage");
243	      ret.B = B.columnwise_data.dptr;
244	      ret.transB = is_B_transposed ? CUBLAS_OP_N : CUBLAS_OP_T;
245	      ret.Btype = B.columnwise_data.dtype;
246	      ret.B_scale_inv = B.columnwise_scale_inv.dptr;
247	      ret.ldb = is_B_transposed ? k : n;
248	    }
249	
250	    if (is_fp8_dtype(ret.Atype)) {
251	      // Requirements from https://docs.nvidia.com/cuda/cublas/#tensor-core-usage
252	      NVTE_CHECK(ret.ldb % 16 == 0,
253	                 "Leading dimension requirement on B for FP8 GEMM. Caller must pad.");
254	    }
255	  } else if (nvfp4) {
256	    if (is_B_transposed) {
257	      NVTE_CHECK(is_nvfp4_scaling(B.scaling_mode),
258	                 "Input B has unsupported combination of recipe and layout");
259	      NVTE_CHECK(B.has_columnwise_data(), "Input B is missing column-wise usage");
260	    } else {
261	      NVTE_CHECK(B.has_data(), "Input B is missing row-wise usage");
262	    }
263	    ret.B = is_B_transposed ? B.columnwise_data.dptr : B.data.dptr;
264	    ret.transB = CUBLAS_OP_N;  // NVFP4 gemm is only supported in TN layout.
265	    ret.Btype = is_B_transposed ? B.columnwise_data.dtype : B.data.dtype;
266	    ret.B_scale_inv = is_B_transposed ? B.columnwise_scale_inv.dptr : B.scale_inv.dptr;
267	    ret.ldb = k;
268	  } else if (mxfp8) {
269	    if (is_B_transposed) {
270	      NVTE_CHECK(B.has_columnwise_data(), "Input B is missing column-wise usage");
271	    } else {
272	      NVTE_CHECK(B.has_data(), "Input B is missing row-wise usage");
273	    }
274	    ret.B = is_B_transposed ? B.columnwise_data.dptr : B.data.dptr;
275	    ret.transB = transB;
276	    ret.Btype = is_B_transposed ? B.columnwise_data.dtype : B.data.dtype;
277	    ret.B_scale_inv = is_B_transposed ? B.columnwise_scale_inv.dptr : B.scale_inv.dptr;
278	    ret.ldb = is_B_transposed ? n : k;
279	  } else if (B.scaling_mode == NVTE_BLOCK_SCALING_1D || B.scaling_mode == NVTE_BLOCK_SCALING_2D) {
280	    // FP8 block scaling
281	    // Note: Hopper only supports TN GEMMs for FP8. "Column-wise data" is transpose of data.
282	    if (is_B_transposed) {
283	      NVTE_CHECK(B.has_columnwise_data(), "Input B is missing column-wise usage");
284	    } else {
285	      NVTE_CHECK(B.has_data(), "Input B is missing row-wise usage");
286	    }
287	    ret.B = is_B_transposed ? B.columnwise_data.dptr : B.data.dptr;
288	    ret.transB = CUBLAS_OP_N;
289	    ret.Btype = is_B_transposed ? B.columnwise_data.dtype : B.data.dtype;
290	    ret.B_scale_inv = is_B_transposed ? B.columnwise_scale_inv.dptr : B.scale_inv.dptr;
291	    ret.ldb = k;
292	
293	    // Requirements from
294	    // https://docs.nvidia.com/cuda/cublas/#tensor-core-usage
295	    NVTE_CHECK((ret.ldb % 16) == 0,
296	               "B tensor stride requirement on NVTE_BLOCK_SCALING GEMM. Caller must pad.");
297	    if (B.scaling_mode == NVTE_BLOCK_SCALING_1D) {
298	      // Observed this requirement only present for B tensor is 1D quantized.
299	      NVTE_CHECK((n % 8) == 0,
300	                 "Outer dimension requirement on B for NVTE_BLOCK_SCALING GEMM. Caller must pad.");
301	    }
302	  } else {
303	    NVTE_ERROR("B has unsupported scaling mode");
304	  }
305	
306	  return ret;
307	}
