316	                 const Tensor *inputBias, Tensor *outputPreGelu, cublasOperation_t transa,
317	                 cublasOperation_t transb, bool grad, void *workspace, size_t workspaceSize,
318	                 const void *alpha, const void *beta, bool use_split_accumulator, int math_sm_count,
319	                 int m_split, int n_split, bool gemm_producer, const Tensor *inputCounter,
320	                 cudaStream_t stream) {
321	  NVTE_CHECK(!inputA->row_scaled_nvfp4 && !inputB->row_scaled_nvfp4,
322	             "cuBLAS GEMM does not support row-scaled NVFP4 inputs.");
323	
324	  // Tensor dims in row-major order
325	  const auto [A0, A1] = inputA->flat_2d_dims();
326	  const auto [B0, B1] = inputB->flat_2d_dims();
327	
328	  // GEMM dims in column-major order
329	  const int m = transa == CUBLAS_OP_T ? A0 : A1;
330	  const int n = transb == CUBLAS_OP_T ? B1 : B0;
331	  const int k = transa == CUBLAS_OP_T ? A1 : A0;
332	  NVTE_CHECK((transb == CUBLAS_OP_T ? B0 : B1) == k,
333	             "GEMM inputs have incompatible dimensions (A is ", A0, "x", A1, ", B is ", B0, "x", B1,
334	             ")");
335	  const int ldd = m;
336	
337	  // Return immediately if GEMM is trivial
338	  if (m <= 0 || n <= 0) {
339	    return;
340	  }
341	  NVTE_CHECK(k > 0);
342	
343	  const GemmParam param = CanonicalizeGemmInput(*inputA, transa, *inputB, transb, m, n, k);
344	
345	  void *C = outputD->data.dptr;
346	  void *D = outputD->data.dptr;
347	  void *D_scale = outputD->scale.dptr;
348	  void *D_amax = outputD->amax.dptr;
349	  void *bias_ptr = inputBias->data.dptr;
350	  const bool bias = bias_ptr != nullptr;
351	  void *pre_gelu_out = outputPreGelu->data.dptr;
352	  void *counter = nullptr;
353	  if (inputCounter != nullptr) {
354	    counter = inputCounter->data.dptr;
355	  }
356	  const bool gelu = pre_gelu_out != nullptr;
357	  const bool use_fp8 = is_fp8_dtype(param.Atype) || is_fp8_dtype(param.Btype);
358	  const bool use_fp4 = is_fp4_dtype(param.Atype) || is_fp4_dtype(param.Btype);
359	
360	  // Update scaling factors with NVFP4 tensor scales
361	  // TODO: Check whether scales are on CPU/GPU or add API to control.
362	  // Currently scales are assumed to be on CPU when amax is provided
363	  // and on GPU when not provided, but this is brittle.
364	  if (use_fp4 &&
365	      ((transa == CUBLAS_OP_T ? inputA->amax.dptr : inputA->columnwise_amax.dptr) != nullptr ||
366	       (transb == CUBLAS_OP_T ? inputB->columnwise_amax.dptr : inputB->amax.dptr) != nullptr)) {
367	    // Reserve some workspace for alpha scale
368	    NVTE_CHECK(workspaceSize >= 4,
369	               "NVFP4 GEMM requires at least 4 byte workspace for alpha scale, but only has ",
370	               workspaceSize, " bytes remaining.");
371	    workspaceSize = (workspaceSize / 4) * 4 - 4;  // Remove last 4 aligned bytes
372	    uint8_t *workspace_ptr = reinterpret_cast<uint8_t *>(workspace);
373	    float *new_alpha_ptr = reinterpret_cast<float *>(&workspace_ptr[workspaceSize]);
374	
375	    // Update alpha scale on device
376	    // Note: Compute NVFP4 tensor scales based on amaxes and then
377	    // divide from alpha scale. This way we only need to apply NVFP4
378	    // tensor scales in matmul output, instead of in matmul inputs.
379	    float old_alpha = *reinterpret_cast<const float *>(alpha);  // Assumed to be on CPU
380	    TensorWrapper new_alpha_tensor(new_alpha_ptr, std::vector<size_t>{1}, DType::kFloat32);
381	    bool a_rowwise_amax = transa == CUBLAS_OP_T;
382	    bool b_rowwise_amax = transb != CUBLAS_OP_T;
383	    nvte_nvfp4_compute_per_tensor_scale(inputA->nvte_tensor, a_rowwise_amax, inputB->nvte_tensor,
384	                                        b_rowwise_amax, old_alpha, new_alpha_tensor.data(), stream);
385	    alpha = new_alpha_ptr;
386	
387	    // Make sure beta scale is on device
388	    float old_beta = *reinterpret_cast<const float *>(beta);  // Assumed to be on CPU
389	    if (old_beta == 0) {
390	      beta = GetScalarZero();  // Device constant memory
391	    } else if (old_beta == 1) {
392	      beta = GetScalarOne();  // Device constant memory
393	    } else {
394	      // Move beta to workspace
395	      NVTE_CHECK(workspaceSize >= 4,
396	                 "NVFP4 GEMM requires at least 4 byte workspace for beta scale, but only has ",
397	                 workspaceSize, " bytes remaining.");
398	      workspaceSize = (workspaceSize / 4) * 4 - 4;  // Remove last 4 aligned bytes
399	      float *new_beta_ptr = reinterpret_cast<float *>(&workspace_ptr[workspaceSize]);
400	      set_float_kernel<<<1, 1, 0, stream>>>(new_beta_ptr, old_beta);
401	      NVTE_CHECK_CUDA(cudaGetLastError());
402	      beta = new_beta_ptr;
403	    }
404	  }
405	
406	  const cudaDataType_t A_type = get_cuda_dtype(param.Atype);
407	  const cudaDataType_t B_type = get_cuda_dtype(param.Btype);
408	  const cudaDataType_t D_type = get_cuda_dtype(outputD->data.dtype);
409	  const cudaDataType_t bias_type = get_cuda_dtype(inputBias->data.dtype);
410	
411	  NVTE_CHECK(!is_fp8_dtype(param.Atype) || param.A_scale_inv != nullptr,
412	             "FP8 input to GEMM requires inverse of scale!");
413	  NVTE_CHECK(!is_fp8_dtype(param.Btype) || param.B_scale_inv != nullptr,
414	             "FP8 input to GEMM requires inverse of scale!");
415	  NVTE_CHECK(!is_fp4_dtype(param.Atype) || param.A_scale_inv != nullptr,
416	             "FP4 input to GEMM requires inverse of scale!");
417	  NVTE_CHECK(!is_fp4_dtype(param.Btype) || param.B_scale_inv != nullptr,
418	             "FP4 input to GEMM requires inverse of scale!");
419	
420	  // check consistency of arguments:
421	  // if fp8 is desired, context cannot be null
422	  // fp8 + gelu fusion + fp8 aux is unavailable right now.
423	  if ((use_fp8 || use_fp4) && gelu) {
424	    NVTE_CHECK(!is_fp8_dtype(outputPreGelu->data.dtype),
425	               "fp8 Aux output for gemm + gelu fusion not supported!");
426	  }
427	  if (is_fp4_dtype(outputD->data.dtype)) {
428	    NVTE_ERROR("FP4 GEMM output is not supported!");
429	  }
430	  if (use_fp4 && (D_type == CUDA_R_16F)) {
431	    NVTE_ERROR("FP4 GEMM does not support FP16 output!");
432	  }
433	
434	  cublasLtHandle_t handle = cublasHandleManager::Instance().GetHandle();
435	
436	  cublasLtMatmulDesc_t operationDesc = nullptr;
437	  cublasLtMatrixLayout_t Adesc = nullptr, Bdesc = nullptr, Cdesc = nullptr, Ddesc = nullptr;
438	  cublasLtMatmulPreference_t preference = nullptr;
439	  int returnedResults = 0;
440	  cublasLtMatmulHeuristicResult_t heuristicResult = {};
441	  cublasLtEpilogue_t epilogue = CUBLASLT_EPILOGUE_DEFAULT;
442	
443	  int64_t ld_gelumat = (int64_t)ldd;
444	
445	  // Use TF32 only for pure FP32 GEMM.
446	  cublasComputeType_t gemm_compute_type = CUBLAS_COMPUTE_32F;
447	  if (A_type == CUDA_R_32F && B_type == CUDA_R_32F && D_type == CUDA_R_32F) {
448	    gemm_compute_type = CUBLAS_COMPUTE_32F_FAST_TF32;
449	  }
450

450	
451	  // Create matrix descriptors. Not setting any extra attributes.
452	  NVTE_CHECK_CUBLAS(cublasLtMatrixLayoutCreate(&Adesc, A_type, param.transA == CUBLAS_OP_N ? m : k,
453	                                               param.transA == CUBLAS_OP_N ? k : m, param.lda));
454	  NVTE_CHECK_CUBLAS(cublasLtMatrixLayoutCreate(&Bdesc, B_type, param.transB == CUBLAS_OP_N ? k : n,
455	                                               param.transB == CUBLAS_OP_N ? n : k, param.ldb));
456	
457	  NVTE_CHECK_CUBLAS(cublasLtMatrixLayoutCreate(&Ddesc, D_type, m, n, ldd));
458	
459	  NVTE_CHECK_CUBLAS(cublasLtMatmulDescCreate(&operationDesc, gemm_compute_type, CUDA_R_32F));
460	  NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(operationDesc, CUBLASLT_MATMUL_DESC_TRANSA,
461	                                                   &param.transA, sizeof(param.transA)));
462	  NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(operationDesc, CUBLASLT_MATMUL_DESC_TRANSB,
463	                                                   &param.transB, sizeof(param.transB)));
464	  // Set math SM count
465	  if (math_sm_count != 0) {
466	    NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(operationDesc,
467	                                                     CUBLASLT_MATMUL_DESC_SM_COUNT_TARGET,
468	                                                     &math_sm_count, sizeof(math_sm_count)));
469	  }
470	
471	  // set fp8/fp4 attributes -- input and output types should already be set to fp8/fp4
472	  // as appropriate. Note: gelu fusion isn't available right now, and we don't need
473	  // amax(D) either (next op is high precision).
474	  const bool mxfp8_gemm = !use_fp4 && is_mxfp8_scaling(inputA->scaling_mode);
475	
476	  if (use_fp8 || use_fp4) {
477	    // Fast accumulation is only supported for FP8.
478	    const int8_t fastAccuMode = (use_split_accumulator) ? 0 : use_fp8;
479	    NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(operationDesc, CUBLASLT_MATMUL_DESC_FAST_ACCUM,
480	                                                     &fastAccuMode, sizeof(fastAccuMode)));
481	
482	    // Scaling factors.
483	#if CUBLAS_VERSION >= 120800
484	    cublasLtMatmulMatrixScale_t scaling_mode_a;
485	    cublasLtMatmulMatrixScale_t scaling_mode_b;
486	#endif  // CUBLAS_VERSION >= 120800
487	    if (is_tensor_scaling(inputA->scaling_mode) && is_tensor_scaling(inputB->scaling_mode)) {
488	      void *A_scale_inverse = param.A_scale_inv;
489	      void *B_scale_inverse = param.B_scale_inv;
490	      NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(operationDesc,
491	                                                       CUBLASLT_MATMUL_DESC_A_SCALE_POINTER,
492	                                                       &A_scale_inverse, sizeof(A_scale_inverse)));
493	      NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(operationDesc,
494	                                                       CUBLASLT_MATMUL_DESC_B_SCALE_POINTER,
495	                                                       &B_scale_inverse, sizeof(B_scale_inverse)));
496	#if CUBLAS_VERSION >= 120800
497	      scaling_mode_a = CUBLASLT_MATMUL_MATRIX_SCALE_SCALAR_32F;
498	      scaling_mode_b = CUBLASLT_MATMUL_MATRIX_SCALE_SCALAR_32F;
499	#endif  // CUBLAS_VERSION >= 120800
500	    } else if (mxfp8_gemm) {
501	#if CUBLAS_VERSION >= 120800
502	      NVTE_CHECK(transformer_engine::cuda::cublas_version() >= 120800,
503	                 "MXFP8 requires cuBLAS 12.8+, but run-time cuBLAS version is ",
504	                 transformer_engine::cuda::cublas_version());
505	
506	      // Check that scales are in expected format
507	      NVTE_CHECK(inputA->with_gemm_swizzled_scales,
508	                 "MXFP8 scales are not in format expected by GEMM");
509	      NVTE_CHECK(inputB->with_gemm_swizzled_scales,
510	                 "MXFP8 scales are not in format expected by GEMM");
511	
512	      // Configure cuBLAS scales
513	      fp8e8m0 *A_scale_inverse = reinterpret_cast<fp8e8m0 *>(param.A_scale_inv);
514	      fp8e8m0 *B_scale_inverse = reinterpret_cast<fp8e8m0 *>(param.B_scale_inv);
515	      NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(operationDesc,
516	                                                       CUBLASLT_MATMUL_DESC_A_SCALE_POINTER,
517	                                                       &A_scale_inverse, sizeof(A_scale_inverse)));
518	      NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(operationDesc,
519	                                                       CUBLASLT_MATMUL_DESC_B_SCALE_POINTER,
520	                                                       &B_scale_inverse, sizeof(B_scale_inverse)));
521	      scaling_mode_a = CUBLASLT_MATMUL_MATRIX_SCALE_VEC32_UE8M0;
522	      scaling_mode_b = CUBLASLT_MATMUL_MATRIX_SCALE_VEC32_UE8M0;
523	
524	      // Workaround for heuristic cache bug in cublasLt. This separates the MXFP8 cache key from non-block scaling.
525	      // CUBLASLT_MATMUL_DESC_ALPHA_VECTOR_BATCH_STRIDE is unused for block scaling so it's safe to set.
526	      if (transformer_engine::cuda::cublas_version() <= 120803) {
527	        const int64_t dummy_a_vec_stride = 1;
528	        NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(
529	            operationDesc, CUBLASLT_MATMUL_DESC_ALPHA_VECTOR_BATCH_STRIDE, &dummy_a_vec_stride,
530	            sizeof(dummy_a_vec_stride)));
531	      }
532	#else
533	      NVTE_ERROR("MXFP8 requires cuBLAS 12.8+, but compile-time cuBLAS version is ",
534	                 CUBLAS_VERSION);
535	#endif                     // CUBLAS_VERSION >= 120800
536	    } else if (use_fp4) {  // NVFP4 GEMM
537	#if CUBLAS_VERSION >= 120800
538	      NVTE_CHECK(transformer_engine::cuda::cublas_version() >= 120800,
539	                 "FP4 requires cuBLAS 12.8+, but run-time cuBLAS version is ",
540	                 transformer_engine::cuda::cublas_version());
541	
542	      // Check that scales are in expected format
543	      NVTE_CHECK(inputA->with_gemm_swizzled_scales,
544	                 "NVFP4 block scales are not in format expected by GEMM");
545	      NVTE_CHECK(inputB->with_gemm_swizzled_scales,
546	                 "NVFP4 block scales are not in format expected by GEMM");
547	
548	      // alpha and beta are device pointers to FP32
549	      const cublasDataType_t scale_type = CUDA_R_32F;
550	      NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(
551	          operationDesc, CUBLASLT_MATMUL_DESC_SCALE_TYPE, &scale_type, sizeof(scale_type)));
552	      const cublasLtPointerMode_t pointer_mode = CUBLASLT_POINTER_MODE_DEVICE;
553	      NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(
554	          operationDesc, CUBLASLT_MATMUL_DESC_POINTER_MODE, &pointer_mode, sizeof(pointer_mode)));
555	
556	      // Configure cuBLAS scales
557	      fp8e4m3 *A_scale_inverse = reinterpret_cast<fp8e4m3 *>(param.A_scale_inv);
558	      fp8e4m3 *B_scale_inverse = reinterpret_cast<fp8e4m3 *>(param.B_scale_inv);
559	      NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(operationDesc,
560	                                                       CUBLASLT_MATMUL_DESC_A_SCALE_POINTER,
561	                                                       &A_scale_inverse, sizeof(A_scale_inverse)));
562	      NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(operationDesc,
563	                                                       CUBLASLT_MATMUL_DESC_B_SCALE_POINTER,
564	                                                       &B_scale_inverse, sizeof(B_scale_inverse)));
565	      scaling_mode_a = CUBLASLT_MATMUL_MATRIX_SCALE_VEC16_UE4M3;
566	      scaling_mode_b = CUBLASLT_MATMUL_MATRIX_SCALE_VEC16_UE4M3;
567	#else
568	      NVTE_ERROR("FP4 requires cuBLAS 12.8+, but compile-time cuBLAS version is ", CUBLAS_VERSION);
569	#endif  // CUBLAS_VERSION >= 120800
570	    } else if ((inputA->scaling_mode == NVTE_BLOCK_SCALING_1D ||
571	                inputA->scaling_mode == NVTE_BLOCK_SCALING_2D) &&
572	               (inputB->scaling_mode == NVTE_BLOCK_SCALING_1D ||
573	                inputB->scaling_mode == NVTE_BLOCK_SCALING_2D)) {
574	#if CUBLAS_VERSION >= 120900
575	      NVTE_CHECK(transformer_engine::cuda::cublas_version() >= 120900,
576	                 "FP8 block scaling requires cuBLAS 12.9+, but run-time cuBLAS version is ",
577	                 transformer_engine::cuda::cublas_version());
578	
579	      // Check that matrix formats are valid
580	      NVTE_CHECK((!(inputA->scaling_mode == NVTE_BLOCK_SCALING_2D &&
581	                    inputB->scaling_mode == NVTE_BLOCK_SCALING_2D)),
582	                 "Only 1D by 1D, 1D by 2D, and 2D by 1D block scaling GEMM is supported, "
583	                 "but got 2D by 2D");
584	
585	      // Configure cuBLAS scales
586	      float *A_scale_inverse = reinterpret_cast<float *>(param.A_scale_inv);
587	      float *B_scale_inverse = reinterpret_cast<float *>(param.B_scale_inv);
588	      NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(operationDesc,
589	                                                       CUBLASLT_MATMUL_DESC_A_SCALE_POINTER,
590	                                                       &A_scale_inverse, sizeof(A_scale_inverse)));
591	      NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(operationDesc,
592	                                                       CUBLASLT_MATMUL_DESC_B_SCALE_POINTER,
593	                                                       &B_scale_inverse, sizeof(B_scale_inverse)));
594	      scaling_mode_a = inputA->scaling_mode == NVTE_BLOCK_SCALING_1D
595	                           ? CUBLASLT_MATMUL_MATRIX_SCALE_VEC128_32F
596	                           : CUBLASLT_MATMUL_MATRIX_SCALE_BLK128x128_32F;
597	      scaling_mode_b = inputB->scaling_mode == NVTE_BLOCK_SCALING_1D
598	                           ? CUBLASLT_MATMUL_MATRIX_SCALE_VEC128_32F
599	                           : CUBLASLT_MATMUL_MATRIX_SCALE_BLK128x128_32F;
600	#else
601	      NVTE_ERROR("FP8 block scaling requires cuBLAS 12.9+, but compile-time cuBLAS version is ",
602	                 CUBLAS_VERSION);
603	#endif  // CUBLAS_VERSION >= 120900
604	    } else {
605	      NVTE_ERROR("Not implemented scaling modes: " + to_string(inputA->scaling_mode) + " and  " +
606	                 to_string(inputB->scaling_mode) + ".");
607	    }
608	
609	#if CUBLAS_VERSION >= 120800
610	    if (transformer_engine::cuda::cublas_version() >= 120800) {
611	      NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(operationDesc,
612	                                                       CUBLASLT_MATMUL_DESC_A_SCALE_MODE,
613	                                                       &scaling_mode_a, sizeof(scaling_mode_a)));
614	      NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(operationDesc,
615	                                                       CUBLASLT_MATMUL_DESC_B_SCALE_MODE,
616	                                                       &scaling_mode_b, sizeof(scaling_mode_b)));
617	    }
618	#endif  // CUBLAS_VERSION >= 120800
619	    if (is_fp8_dtype(outputD->data.dtype)) {
620	      // Accumulation mode not supported for FP8 output
621	      C = nullptr;
622	      NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(
623	          operationDesc, CUBLASLT_MATMUL_DESC_D_SCALE_POINTER, &D_scale, sizeof(D_scale)));
624	      NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(
625	          operationDesc, CUBLASLT_MATMUL_DESC_AMAX_D_POINTER, &D_amax, sizeof(D_amax)));
626	#if CUBLAS_VERSION >= 120800
627	      if (transformer_engine::cuda::cublas_version() >= 120800) {
628	        // NOTE: In all current cases where FP8 output is supported, the input is
629	        // scaled identically to the output.
630	        NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(operationDesc,
631	                                                         CUBLASLT_MATMUL_DESC_D_SCALE_MODE,
632	                                                         &scaling_mode_a, sizeof(scaling_mode_a)));
633	      }
634	#endif  // CUBLAS_VERSION >= 120800
635	      // For FP8 output, cuBLAS requires C_type to match bias_type and
636	      // be FP16/BF16
637	      const cudaDataType_t C_type = bias ? bias_type : CUDA_R_16BF;
638	      NVTE_CHECK_CUBLAS(cublasLtMatrixLayoutCreate(&Cdesc, C_type, m, n, ldd));
639	    } else {
640	      NVTE_CHECK_CUBLAS(cublasLtMatrixLayoutCreate(&Cdesc, D_type, m, n, ldd));
641	    }
642	    if (bias) {
643	      NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(
644	          operationDesc, CUBLASLT_MATMUL_DESC_BIAS_DATA_TYPE, &bias_type, sizeof(bias_type)));
645	    }
646	  } else {
647	    NVTE_CHECK_CUBLAS(cublasLtMatrixLayoutCreate(&Cdesc, D_type, m, n, ldd));
648	  }
649	
650	  if (bias && gelu) {
651	    if (grad) {
652	      epilogue = CUBLASLT_EPILOGUE_DGELU_BGRAD;
653	    } else {
654	      epilogue = CUBLASLT_EPILOGUE_GELU_AUX_BIAS;
655	    }
656	    NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(
657	        operationDesc, CUBLASLT_MATMUL_DESC_BIAS_POINTER, &bias_ptr, sizeof(bias_ptr)));
658	    NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(operationDesc,
659	                                                     CUBLASLT_MATMUL_DESC_EPILOGUE_AUX_POINTER,
660	                                                     &pre_gelu_out, sizeof(pre_gelu_out)));
661	    NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(
662	        operationDesc, CUBLASLT_MATMUL_DESC_EPILOGUE_AUX_LD, &ld_gelumat, sizeof(ld_gelumat)));
663	    const cudaDataType_t aux_type = get_cuda_dtype(outputPreGelu->data.dtype);
664	    NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(
665	        operationDesc, CUBLASLT_MATMUL_DESC_EPILOGUE_AUX_DATA_TYPE, &aux_type, sizeof(aux_type)));
666	  } else if (bias) {
667	    if (grad) {
668	      // grad output is always input B
669	      epilogue = CUBLASLT_EPILOGUE_BGRADB;
670	    } else {
671	      epilogue = CUBLASLT_EPILOGUE_BIAS;
672	    }
673	    NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(
674	        operationDesc, CUBLASLT_MATMUL_DESC_BIAS_POINTER, &bias_ptr, sizeof(bias_ptr)));
675	  } else if (gelu) {
676	    if (grad) {
677	      epilogue = CUBLASLT_EPILOGUE_DGELU;
678	    } else {
679	      epilogue = CUBLASLT_EPILOGUE_GELU_AUX;
680	    }
681	    NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(operationDesc,
682	                                                     CUBLASLT_MATMUL_DESC_EPILOGUE_AUX_POINTER,
683	                                                     &pre_gelu_out, sizeof(pre_gelu_out)));
684	    NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(
685	        operationDesc, CUBLASLT_MATMUL_DESC_EPILOGUE_AUX_LD, &ld_gelumat, sizeof(ld_gelumat)));
686	    const cudaDataType_t aux_type = get_cuda_dtype(outputPreGelu->data.dtype);
687	    NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(
688	        operationDesc, CUBLASLT_MATMUL_DESC_EPILOGUE_AUX_DATA_TYPE, &aux_type, sizeof(aux_type)));
689	  }
690	
691	  if ((inputA->scaling_mode == NVTE_BLOCK_SCALING_1D) ||
692	      (inputA->scaling_mode == NVTE_BLOCK_SCALING_2D)) {
693	    NVTE_CHECK((epilogue == CUBLASLT_EPILOGUE_DEFAULT || epilogue == CUBLASLT_EPILOGUE_BIAS ||
694	                epilogue == CUBLASLT_EPILOGUE_DGELU),
695	               "Epilogue requested outside of the available and tested cuBLAS functionality for "
696	               "float8 block scaled GEMM");
697	  }
698	
699	  NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(operationDesc, CUBLASLT_MATMUL_DESC_EPILOGUE,
700	                                                   &epilogue, sizeof(epilogue)));
701	
702	  if (counter != nullptr) {
703	#if !(CUDA_VERSION >= 12020 && CUDA_VERSION < 13000)
704	    NVTE_ERROR("Atomic GEMM requires CUDA >=12.2.0 and <13.0.0, but compile-time CUDA version is ",
705	               CUDA_VERSION);
706	#elif !(CUBLAS_VERSION >= 120205 && CUBLAS_VERSION < 130000)
707	    NVTE_ERROR(
708	        "Atomic GEMM requires cuBLAS >=12.2.5 and <13.0.0, but compile-time cuBLAS version is ",
709	        CUBLAS_VERSION);
710	#else
711	    NVTE_CHECK(transformer_engine::cuda::cudart_version() >= 12020 &&
712	                   transformer_engine::cuda::cudart_version() < 13000,
713	               "Atomic GEMM requires CUDA >=12.2.0 and <13.0.0, but run-time CUDA version is ",
714	               transformer_engine::cuda::cudart_version());
715	    NVTE_CHECK(transformer_engine::cuda::cublas_version() >= 120205 &&
716	                   transformer_engine::cuda::cublas_version() < 130000,
717	               "Atomic GEMM requires cuBLAS >=12.2.5 and <13.0.0, but run-time cuBLAS version is ",
718	               transformer_engine::cuda::cublas_version());
719	    if (m_split == 0) m_split = 1;
720	    if (n_split == 0) n_split = 1;
721	    NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(
722	        operationDesc, CUBLASLT_MATMUL_DESC_ATOMIC_SYNC_NUM_CHUNKS_D_ROWS, &m_split,
723	        sizeof(m_split)));
724	    NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(
725	        operationDesc, CUBLASLT_MATMUL_DESC_ATOMIC_SYNC_NUM_CHUNKS_D_COLS, &n_split,
726	        sizeof(n_split)));
727	    if (gemm_producer) {
728	      NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(
729	          operationDesc, CUBLASLT_MATMUL_DESC_ATOMIC_SYNC_OUT_COUNTERS_POINTER, &counter,
730	          sizeof(counter)));
731	    } else {
732	      NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(
733	          operationDesc, CUBLASLT_MATMUL_DESC_ATOMIC_SYNC_IN_COUNTERS_POINTER, &counter,
734	          sizeof(counter)));
735	    }
736	#endif
737	  }
738	
739	  // align the workspace to 256 B
740	  const int required_alignment = 256;
741	  const auto original_workspace_alignment = _getAlignment(reinterpret_cast<uintptr_t>(workspace));
742	  uint8_t *aligned_workspace_ptr =
743	      reinterpret_cast<uint8_t *>(workspace) + required_alignment - original_workspace_alignment;
744	  workspaceSize = workspaceSize - required_alignment + original_workspace_alignment;
745	  const auto new_workspace_alignment =
746	      _getAlignment(reinterpret_cast<uintptr_t>(aligned_workspace_ptr));
747	  NVTE_CHECK_CUBLAS(cublasLtMatmulPreferenceCreate(&preference));
748	  NVTE_CHECK_CUBLAS(cublasLtMatmulPreferenceSetAttribute(
749	      preference, CUBLASLT_MATMUL_PREF_MAX_WORKSPACE_BYTES, &workspaceSize, sizeof(workspaceSize)));
750	  const auto A_alignment = _getAlignment(reinterpret_cast<uintptr_t>(param.A));
751	  const auto B_alignment = _getAlignment(reinterpret_cast<uintptr_t>(param.B));
752	  const auto C_alignment = _getAlignment(reinterpret_cast<uintptr_t>(C));
753	  const auto D_alignment = _getAlignment(reinterpret_cast<uintptr_t>(D));
754	  NVTE_CHECK_CUBLAS(cublasLtMatmulPreferenceSetAttribute(
755	      preference, CUBLASLT_MATMUL_PREF_MIN_ALIGNMENT_A_BYTES, &A_alignment, sizeof(A_alignment)));
756	  NVTE_CHECK_CUBLAS(cublasLtMatmulPreferenceSetAttribute(
757	      preference, CUBLASLT_MATMUL_PREF_MIN_ALIGNMENT_B_BYTES, &B_alignment, sizeof(B_alignment)));
758	  NVTE_CHECK_CUBLAS(cublasLtMatmulPreferenceSetAttribute(
759	      preference, CUBLASLT_MATMUL_PREF_MIN_ALIGNMENT_C_BYTES, &C_alignment, sizeof(C_alignment)));
760	  NVTE_CHECK_CUBLAS(cublasLtMatmulPreferenceSetAttribute(
761	      preference, CUBLASLT_MATMUL_PREF_MIN_ALIGNMENT_D_BYTES, &D_alignment, sizeof(D_alignment)));
762	  NVTE_CHECK(new_workspace_alignment % 256 == 0,
763	             "cuBLAS workspace pointer must be aligned to 256 bytes, got ",
764	             new_workspace_alignment);
765	
766	  const auto status =
767	      cublasLtMatmulAlgoGetHeuristic(handle, operationDesc, Adesc, Bdesc, Cdesc, Ddesc, preference,
768	                                     1, &heuristicResult, &returnedResults);
769	  NVTE_CHECK(status != CUBLAS_STATUS_NOT_SUPPORTED,
770	             "Unable to find suitable cuBLAS GEMM algorithm");
771	  NVTE_CHECK_CUBLAS(status);
772	  if (returnedResults == 0) NVTE_ERROR("Unable to find any suitable algorithms");
773	
774	  // D = alpha * (A * B) + beta * C
775	  NVTE_CHECK_CUBLAS(cublasLtMatmul(handle, operationDesc, alpha, /* alpha */
776	                                   param.A,                      /* A */
777	                                   Adesc, param.B,               /* B */
778	                                   Bdesc, beta,                  /* beta */
779	                                   C,                            /* C */
780	                                   Cdesc, D,                     /* D */
781	                                   Ddesc, &heuristicResult.algo, /* algo */
782	                                   aligned_workspace_ptr,        /* workspace */
783	                                   workspaceSize, stream));      /* stream */
784	
785	  // Update FP8 scale-inv in output tensor
786	  // Note: This is a WAR for the case when we have fp8 output but D->scale_inv is not allocated.
787	  // TODO: Changing gemm interface so that D->scale_inv is allocated and the scale_inv can be
788	  // calculated here.
789	  if (is_fp8_dtype(outputD->data.dtype) && outputD->scale_inv.dptr) {
790	    update_tensor_scale_inv(outputD, stream);
791	  }
792	
793	  NVTE_CHECK_CUBLAS(cublasLtMatmulPreferenceDestroy(preference));
794	  NVTE_CHECK_CUBLAS(cublasLtMatrixLayoutDestroy(Ddesc));
795	  NVTE_CHECK_CUBLAS(cublasLtMatrixLayoutDestroy(Cdesc));
796	  NVTE_CHECK_CUBLAS(cublasLtMatrixLayoutDestroy(Bdesc));
797	  NVTE_CHECK_CUBLAS(cublasLtMatrixLayoutDestroy(Adesc));
798	  NVTE_CHECK_CUBLAS(cublasLtMatmulDescDestroy(operationDesc));
799	}
