803	void nvte_cublas_gemm(const NVTETensor A, const NVTETensor B, NVTETensor D, const NVTETensor bias,
804	                      NVTETensor pre_gelu_out, bool transa, bool transb, bool grad,
805	                      NVTETensor workspace, bool accumulate, bool use_split_accumulator,
806	                      int math_sm_count, cudaStream_t stream) {
807	  NVTE_API_CALL(nvte_cublas_gemm);
808	  using namespace transformer_engine;
809	
810	  // Tensors
811	  const Tensor *inputA = convertNVTETensorCheck(A);
812	  const Tensor *inputB = convertNVTETensorCheck(B);
813	  Tensor *outputD = convertNVTETensorCheck(D);
814	  const Tensor *biasTensor = convertNVTETensor(bias);
815	  Tensor *outputGelu = convertNVTETensor(pre_gelu_out);
816	  Tensor *wspace = convertNVTETensor(workspace);
817	
818	  // Scales
819	  const float alpha = 1;
820	  const float beta = accumulate ? 1 : 0;
821	
822	  // Check for NVFP4
823	  // TODO Remove once alpha scale logic is moved into cublas_gemm function
824	  if (is_nvfp_scaling(inputA->scaling_mode) || is_nvfp_scaling(inputB->scaling_mode)) {
825	    NVTE_ERROR("nvte_cublas_gemm does not support NVFP4 data. Use nvte_cublas_gemm_v2 instead.");
826	  }
827	
828	  // Launch GEMM
829	  cublas_gemm(inputA, inputB, outputD, biasTensor, outputGelu, (transa) ? CUBLAS_OP_T : CUBLAS_OP_N,
830	              (transb) ? CUBLAS_OP_T : CUBLAS_OP_N, grad, wspace->data.dptr, wspace->data.shape[0],
831	              &alpha, &beta, use_split_accumulator, math_sm_count, 0, 0, false, nullptr, stream);
832	}
