834	void nvte_cublas_gemm_v2(int transa, int transb, const float *alpha, const NVTETensor A,
835	                         const NVTETensor B, const float *beta, const NVTETensor C, NVTETensor D,
836	                         NVTETensor workspace, NVTEMatmulConfig config, cudaStream_t stream) {
837	  NVTE_API_CALL(nvte_cublas_gemm_v2);
838	  using namespace transformer_engine;
839	
840	  // Data tensors
841	  const Tensor *A_tensor = convertNVTETensorCheck(A);
842	  const Tensor *B_tensor = convertNVTETensorCheck(B);
843	  const Tensor *C_tensor = convertNVTETensorCheck(C);
844	  Tensor *D_tensor = convertNVTETensorCheck(D);
845	  NVTE_CHECK(C_tensor == D_tensor,
846	             "Currently nvte_cublas_gemm_v2 does not support different C and D tensors.");
847	
848	  // Workspace
849	  void *workspace_ptr = nullptr;
850	  size_t workspace_size = 0;
851	  Tensor *workspace_tensor = convertNVTETensor(workspace);
852	  if (workspace_tensor != nullptr) {
853	    workspace_ptr = workspace_tensor->data.dptr;
854	    workspace_size =
855	        get_buffer_size_bytes(workspace_tensor->data.numel(), workspace_tensor->data.dtype);
856	  }
857	
858	  // Additional config
859	  MatmulConfig config_;
860	  if (config != nullptr) {
861	    config_ = *reinterpret_cast<MatmulConfig *>(config);
862	  }
863	
864	  // Configure GEMM epilogue
865	  const bool with_grad_epilogue = (config_.dbias_tensor != nullptr || config_.with_dgelu_epilogue);
866	  if (with_grad_epilogue) {
867	    NVTE_CHECK(config_.bias_tensor == nullptr && !config_.with_gelu_epilogue,
868	               "Invalid epilogue (bias=", config_.bias_tensor != nullptr,
869	               ", dbias=", config_.dbias_tensor != nullptr, ", gelu=", config_.with_gelu_epilogue,
870	               ", dgelu=", config_.with_dgelu_epilogue, ").");
871	  }
872	  Tensor dummy_tensor;
873	  Tensor *epilogue_bias_tensor = &dummy_tensor;
874	  if (!with_grad_epilogue && config_.bias_tensor != nullptr) {
875	    epilogue_bias_tensor = convertNVTETensorCheck(config_.bias_tensor);
876	  } else if (with_grad_epilogue && config_.dbias_tensor != nullptr) {
877	    epilogue_bias_tensor = convertNVTETensorCheck(config_.dbias_tensor);
878	  }
879	  Tensor *epilogue_aux_tensor = &dummy_tensor;
880	  if (config_.with_gelu_epilogue || config_.with_dgelu_epilogue) {
881	    NVTE_CHECK(config_.epilogue_aux_tensor != nullptr,
882	               "Requested epilogue (bias=", config_.bias_tensor != nullptr,
883	               ", dbias=", config_.dbias_tensor != nullptr, ", gelu=", config_.with_gelu_epilogue,
884	               ", dgelu=", config_.with_dgelu_epilogue, ") without providing aux tensor.");
885	    epilogue_aux_tensor = convertNVTETensor(config_.epilogue_aux_tensor);
886	  }
887	
888	  // Launch GEMM
889	  cublas_gemm(A_tensor, B_tensor, D_tensor, epilogue_bias_tensor, epilogue_aux_tensor,
890	              transa ? CUBLAS_OP_T : CUBLAS_OP_N, transb ? CUBLAS_OP_T : CUBLAS_OP_N,
891	              with_grad_epilogue, workspace_ptr, workspace_size, alpha, beta,
892	              config_.use_split_accumulator, config_.sm_count, 0, 0, false, nullptr, stream);
893	}
