970	void multi_stream_cublas_gemm(const NVTETensor *A, const NVTETensor *B, NVTETensor *D,
971	                              const NVTETensor *bias, NVTETensor *pre_gelu_out, const int num_gemms,
972	                              bool transa, bool transb, bool grad, NVTETensor *workspace,
973	                              bool accumulate, bool use_split_accumulator, int math_sm_count,
974	                              cudaStream_t stream) {
975	  using namespace transformer_engine;
976	
977	  int num_streams = nvte_get_num_compute_streams();
978	
979	  int num_stream_used = std::min(num_streams, num_gemms);
980	  // wait for current stream to finish
981	  NVTE_CHECK_CUDA(cudaEventRecord(detail::get_compute_stream_event(0), stream));
982	  for (int s = 0; s < num_stream_used; s++) {
983	    NVTE_CHECK_CUDA(
984	        cudaStreamWaitEvent(detail::get_compute_stream(s), detail::get_compute_stream_event(0)));
985	  }
986	
987	  for (int i = 0; i < num_gemms; i++) {
988	    // Check whether GELU or dGELU epilogue is requested
989	    Tensor *pre_gelu_tensor = convertNVTETensor(pre_gelu_out[i]);
990	    bool with_gelu_dgelu_epilogue =
991	        (pre_gelu_tensor != nullptr && pre_gelu_tensor->data.dptr != nullptr);
992	
993	    // Construct config
994	    MatmulConfig config;
995	    if (grad) {
996	      config.dbias_tensor = bias[i];
997	      config.with_dgelu_epilogue = with_gelu_dgelu_epilogue;
998	    } else {
999	      config.bias_tensor = bias[i];
1000	      config.with_gelu_epilogue = with_gelu_dgelu_epilogue;
1001	    }
1002	    config.epilogue_aux_tensor = pre_gelu_out[i];
1003	    config.use_split_accumulator = use_split_accumulator;
1004	    config.sm_count = math_sm_count;
1005	
1006	    // Launch GEMM
1007	    const float alpha = 1.f;
1008	    const float beta = accumulate ? 1.f : 0.f;
1009	    nvte_cublas_gemm_v2(transa, transb, &alpha, A[i], B[i], &beta, D[i], D[i],
1010	                        workspace[i % num_streams], &config,
1011	                        detail::get_compute_stream(i % num_streams));
1012	  }
1013	
1014	  // record events on compute streams
1015	  for (int s = 0; s < num_stream_used; s++) {
1016	    NVTE_CHECK_CUDA(
1017	        cudaEventRecord(detail::get_compute_stream_event(s), detail::get_compute_stream(s)));
1018	  }
1019	  // wait for all compute streams to finish
1020	  for (int s = 0; s < num_stream_used; s++) {
1021	    NVTE_CHECK_CUDA(cudaStreamWaitEvent(stream, detail::get_compute_stream_event(s)));
1022	  }
1023	}
