1052	void nvte_multi_tensor_gemm(const NVTETensor *A, const NVTETensor *B, NVTETensor *D,
1053	                            const NVTETensor *bias, NVTETensor *pre_gelu_out, const int num_gemms,
1054	                            bool transa, bool transb, bool grad, NVTETensor *workspace,
1055	                            bool accumulate, bool use_split_accumulator, int math_sm_count,
1056	                            cudaStream_t stream) {
1057	  NVTE_API_CALL(nvte_multi_tensor_gemm);
1058	
1059	  if (num_gemms <= 0) {
1060	    return;
1061	  }
1062	
1063	  const int current_device = transformer_engine::cuda::current_device();
1064	  const bool is_hopper = (transformer_engine::cuda::sm_arch(current_device) == 90);
1065	  const bool use_cutlass = transformer_engine::getenv<bool>("NVTE_USE_CUTLASS_GROUPED_GEMM", false);
1066	  const bool warn_fallback =
1067	      transformer_engine::getenv<bool>("NVTE_CUTLASS_GROUPED_GEMM_WARN_FALLBACK", false);
1068	
1069	  auto cublas_path = [&]() {
1070	    multi_stream_cublas_gemm(A, B, D, bias, pre_gelu_out, num_gemms, transa, transb, grad,
1071	                             workspace, accumulate, use_split_accumulator, math_sm_count, stream);
1072	  };
1073	
1074	  // Currently only support cutlass group gemm on Hopper Arch
1075	  if (!(is_hopper && use_cutlass)) {
1076	    cublas_path();
1077	    return;
1078	  }
1079	
1080	  auto is_empty_arr = [&](const NVTETensor *p) -> bool {
1081	    if (p == nullptr) return true;
1082	    for (int i = 0; i < num_gemms; ++i) {
1083	      if (transformer_engine::convertNVTETensor(p[i])->has_data()) return false;
1084	    }
1085	    return true;
1086	  };
1087	
1088	  auto all_groups_uniform_k128 = [&](const NVTETensor *p, bool trans) -> bool {
1089	    int64_t ref_k = -1;
1090	    for (size_t i = 0; i < num_gemms; i++) {
1091	      const auto tensor = transformer_engine::convertNVTETensorCheck(p[i]);
1092	      const int k = trans ? tensor->data.shape[0] : tensor->data.shape[1];
1093	
1094	      if ((k & 127) != 0) return false;
1095	
1096	      if (ref_k < 0)
1097	        ref_k = k;
1098	      else if (k != ref_k)
1099	        return false;
1100	    }
1101	
1102	    return true;
1103	  };
1104	
1105	  auto is_supported_dtype = [&]() -> bool {
1106	    auto *inputA = transformer_engine::convertNVTETensorCheck(A[0]);
1107	    auto *inputB = transformer_engine::convertNVTETensorCheck(B[0]);
1108	    auto *OutputD = transformer_engine::convertNVTETensorCheck(D[0]);
1109	    auto A_type = get_cuda_dtype(inputA->data.dtype);
1110	    auto B_type = get_cuda_dtype(inputB->data.dtype);
1111	    auto D_type = get_cuda_dtype(OutputD->data.dtype);
1112	
1113	    return (A_type == B_type) && (A_type == D_type) &&
1114	           ((A_type == CUDA_R_16BF) || (A_type == CUDA_R_16F));
1115	  };
1116	
1117	  // CUTLASS Grouped GEMM fast path (SM90/TMA)
1118	  // Conditions:
1119	  //  - No fused epilogue: both bias and pre_gelu_out are empty.
1120	  //  - Supported dtypes only: FP16/BF16 (FP32 accumulate).
1121	  //  - Uniform K across groups and K % 128 == 0.
1122	  //  - use_split_accumulator is ignored for FP16/BF16.
1123	  //  - grad is irrelevant when bias/pre_gelu_out are empty.
1124	  //
1125	  // Otherwise, fall back to cuBLAS.
1126	  if (is_empty_arr(bias) && is_empty_arr(pre_gelu_out) && is_supported_dtype() &&
1127	      all_groups_uniform_k128(B, transb)) {
1128	    cutlass_grouped_gemm(A, B, D, num_gemms, transa, transb, grad, workspace, accumulate,
1129	                         current_device, math_sm_count, stream);
1130	  } else {
1131	    if (warn_fallback) {
1132	      NVTE_WARN("Fallback to cuBLAS grouped GEMM.");
1133	    }
1134	    cublas_path();
1135	  }

