976	inline cublasLtMatmulAlgo_t select_grouped_gemm_algo(cublasLtHandle_t handle,
977	                                                     cublasLtMatmulDescOpaque_t &matmulDesc,
978	                                                     cublasLtMatrixLayoutOpaque_t &descA,
979	                                                     cublasLtMatrixLayoutOpaque_t &descB,
980	                                                     cublasLtMatrixLayoutOpaque_t &descC,
981	                                                     cublasLtMatrixLayoutOpaque_t &descD,
982	                                                     int64_t avg_m, int64_t avg_n, int64_t avg_k) {
983	  cublasLtMatmulPreferenceOpaque_t preference;
