985	  NVTE_CHECK_CUBLAS(
986	      cublasLtMatmulPreferenceSetAttribute(&preference, CUBLASLT_MATMUL_PREF_MAX_WORKSPACE_BYTES,
987	                                           &kGroupedGemmCublasWorkspaceSize, sizeof(size_t)));
988	  NVTE_CHECK_CUBLAS(cublasLtMatmulPreferenceSetAttribute(
989	      &preference, CUBLASLT_MATMUL_PREF_GROUPED_DESC_D_AVERAGE_ROWS, &avg_m, sizeof(int64_t)));
990	  NVTE_CHECK_CUBLAS(cublasLtMatmulPreferenceSetAttribute(
991	      &preference, CUBLASLT_MATMUL_PREF_GROUPED_DESC_D_AVERAGE_COLS, &avg_n, sizeof(int64_t)));
992	  NVTE_CHECK_CUBLAS(cublasLtMatmulPreferenceSetAttribute(
993	      &preference, CUBLASLT_MATMUL_PREF_GROUPED_AVERAGE_REDUCTION_DIM, &avg_k, sizeof(int64_t)));
994	
995	  cublasLtMatmulHeuristicResult_t heuristicResult;
996	  int returnedResults = 0;
997	  auto status = cublasLtMatmulAlgoGetHeuristic(handle, &matmulDesc, &descA, &descB, &descC, &descD,
998	                                               &preference, 1, &heuristicResult, &returnedResults);
999	  NVTE_CHECK(status != CUBLAS_STATUS_NOT_SUPPORTED,
1000	             "Unable to find suitable cuBLAS grouped GEMM algorithm");
1001	  NVTE_CHECK_CUBLAS(status);
1002	  NVTE_CHECK(returnedResults > 0, "No suitable algorithm found for grouped GEMM");
1003	  return heuristicResult.algo;
1004	}
