1048	  init_matmul_desc(matmulDesc, op_A, op_B, config.use_fp8, config.use_split_accumulator,
1049	                   config.use_per_group_alpha_beta);
1050	  if (transformer_engine::is_mxfp_scaling(A_sel.scaling_mode)) {
1051	    set_mxfp8_scale_pointers(matmulDesc, setup_workspace.a_scale_inv_ptrs,
1052	                             setup_workspace.b_scale_inv_ptrs);
1053	  } else if (transformer_engine::is_nvfp_scaling(A_sel.scaling_mode)) {
1054	    set_nvfp4_scale_pointers(matmulDesc, setup_workspace.a_scale_inv_ptrs,
1055	                             setup_workspace.b_scale_inv_ptrs);
1056	  } else if (transformer_engine::is_fp8_block_scaling(A_sel.scaling_mode)) {
1057	    set_fp8_block_scaling_scale_pointers(matmulDesc, setup_workspace.a_scale_inv_ptrs,
1058	                                         setup_workspace.b_scale_inv_ptrs, A_sel.scaling_mode,
1059	                                         B_sel.scaling_mode);
1060	  } else if (config.use_fp8) {
1061	    const int sm = transformer_engine::cuda::sm_arch(transformer_engine::cuda::current_device());
1062	    if (sm < 100) {
1063	      NVTE_CHECK(transformer_engine::cuda::cublas_version() >=
1064	                     CUBLAS_FP8_TENSOR_SCALING_GROUPED_GEMM_HOPPER_VERSION,
1065	                 "FP8 tensor scaling grouped GEMM on Hopper (SM90) requires cuBLAS 13.5+, "
1066	                 "but run-time cuBLAS version is ",
1067	                 transformer_engine::cuda::cublas_version());
1068	    }
1069	    set_fp8_scale_pointers(matmulDesc, setup_workspace.a_scale_inv_ptrs,
1070	                           setup_workspace.b_scale_inv_ptrs);
1071	  }
1072	  if (config.sm_count != 0) {
1073	    NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(&matmulDesc,
1074	                                                     CUBLASLT_MATMUL_DESC_SM_COUNT_TARGET,
1075	                                                     &config.sm_count, sizeof(config.sm_count)));
1076	  }
1077	  cublasLtMatmulAlgo_t algo = select_grouped_gemm_algo(
1078	      handle, matmulDesc, descA, descB, descC, descD, config.avg_m, config.avg_n, config.avg_k);
