1080	  // Hopper uses a single scalar alpha/beta for the whole grouped GEMM;
1081	  // Blackwell+ uses per-matrix alpha/beta arrays.
1082	  void *alpha_arg = config.use_per_group_alpha_beta
1083	                        ? static_cast<void *>(setup_workspace.alpha_ptrs)
1084	                        : config.alpha_dptr;
1085	  void *beta_arg = config.use_per_group_alpha_beta ? static_cast<void *>(setup_workspace.beta_ptrs)
1086	                                                   : config.beta_dptr;
