1089	                                   setup_workspace.B_ptrs, &descB, beta_arg, setup_workspace.C_ptrs,
1090	                                   &descC, setup_workspace.D_ptrs, &descD, &algo,
1091	                                   cublas_workspace_ptr, kGroupedGemmCublasWorkspaceSize, stream));
1092	}
