1094	// Device helper: compute the element offset for tensor `idx` given shape metadata.
1095	// Three cases:
1096	//   1. Explicit per-tensor offset array provided  → use it directly.
1097	//   2. Per-tensor first/last dims provided but no offsets → cumulative sum of (first*last) products.
1098	//   3. Fully uniform shapes                        → idx * uniform_first * uniform_last.
1099	__forceinline__ __device__ int64_t compute_grouped_tensor_offset(const TensorShapeInfo &meta,
1100	                                                                 size_t idx) {
1101	  if (meta.offsets) {
1102	    return meta.offsets[idx];
1103	  } else if (meta.first_dims != nullptr || meta.last_dims != nullptr) {
1104	    // offset[i] = sum_{j < i} (first_dims[j] * last_dims[j])
1105	    int64_t cumsum = 0;
1106	    for (size_t i = 0; i < idx; i++) {
1107	      int64_t f = meta.first_dims ? meta.first_dims[i] : meta.uniform_first;
1108	      int64_t l = meta.last_dims ? meta.last_dims[i] : meta.uniform_last;
1109	      cumsum += f * l;
1110	    }
1111	    return cumsum;
1112	  } else {
1113	    return static_cast<int64_t>(idx) * meta.uniform_first * meta.uniform_last;
1114	  }
1115	}
