1117	__forceinline__ __device__ int64_t padded_mxfp8_scale_inv_bytes(int64_t first, int64_t last,
1118	                                                                bool rowwise) {
1119	  namespace mxfp8_swizzle = transformer_engine::dispatch::mxfp8::swizzle;
1120	  constexpr int64_t kMxfp8BlockSize = 32;
1121	  // x is the dimension along which quantization is applied, y is other dimension
1122	  const int64_t scale_tile_y = static_cast<int64_t>(mxfp8_swizzle::GEMM_SWIZZLED_SCALE_TILE_DIM_Y);
1123	  const int64_t scale_tile_x = static_cast<int64_t>(mxfp8_swizzle::GEMM_SWIZZLED_SCALE_TILE_DIM_X);
1124	  // Padded byte size of the swizzled MXFP8 scale_inv for a single tensor with data
1125	  // shape (first, last). Rowwise scales use rows=first, cols=last; columnwise
1126	  // scales swap the orientation since they are stored in column-major order.
1127	  const int64_t scale_dim_y = rowwise ? first : last;
1128	  const int64_t padded_scale_dim_y =
1129	      ((scale_dim_y + scale_tile_y - 1) / scale_tile_y) * scale_tile_y;
1130	  const int64_t data_dim_x = rowwise ? last : first;
1131	  const int64_t scale_dim_x = (data_dim_x + kMxfp8BlockSize - 1) / kMxfp8BlockSize;
1132	  const int64_t padded_scale_dim_x =
1133	      ((scale_dim_x + scale_tile_x - 1) / scale_tile_x) * scale_tile_x;
1134	  // MXFP8 scales are E8M0 (1 byte per element), so element count == byte count.
1135	  return padded_scale_dim_y * padded_scale_dim_x;
1136	}
