1319	    // Output arrays
1320	    void **A_ptrs, void **B_ptrs, void **C_ptrs, void **D_ptrs, int *a_rows, int *a_cols,
1321	    int *b_rows, int *b_cols, int *d_rows, int *d_cols, float **alpha_ptrs, float **beta_ptrs,
1322	    void **a_scale_inv_ptrs, void **b_scale_inv_ptrs,
1323	    // Inputs
1324	    char *a_base, char *b_base, char *c_base, char *d_base, TensorShapeInfo A_meta,
1325	    TensorShapeInfo B_meta, TensorShapeInfo C_meta, TensorShapeInfo D_meta, size_t a_bits_per_elem,
1326	    size_t b_bits_per_elem, size_t c_elem_size, size_t d_elem_size, float *alpha_ptr,
1327	    float *beta_ptr, bool use_per_group_alpha_beta, bool a_is_discrete, bool c_is_discrete,
1328	    bool d_is_discrete,
1329	    // Scale inputs: for tensor scaling, pass float* and set mxfp8_base to nullptr
1330	    // For MXFP8, pass nullptr for tensor_scale and set mxfp8_base
1331	    float *a_scale_base, float *b_scale_base, bool a_rowwise, bool b_rowwise,
1332	    bool a_storage_transposed, bool b_storage_transposed, NVTEScalingMode a_scaling_mode,
1333	    NVTEScalingMode b_scaling_mode, size_t num_tensors,
1334	    MultiTensorGroupGemmInputArgs a_multi_tensor_args,
1335	    MultiTensorGroupGemmOutputArgs c_multi_tensor_args,
1336	    MultiTensorGroupGemmOutputArgs d_multi_tensor_args,
1337	    // NVFP4: per-group amax values and output buffer for computed alpha
1338	    float *a_amax, float *b_amax, float *nvfp4_computed_alpha) {
1339	  size_t idx = blockIdx.x * blockDim.x + threadIdx.x;
1340	  if (idx >= num_tensors) return;
1341	
1342	  // Get dimensions for this tensor (from array or uniform value)
1343	  int64_t a_first = 0;
1344	  int64_t a_last = 0;
1345	  if (!a_is_discrete) {
1346	    a_first = A_meta.first_dims ? A_meta.first_dims[idx] : A_meta.uniform_first;
1347	    a_last = A_meta.last_dims ? A_meta.last_dims[idx] : A_meta.uniform_last;
1348	  }
1349	  int64_t b_first = B_meta.first_dims ? B_meta.first_dims[idx] : B_meta.uniform_first;
1350	  int64_t b_last = B_meta.last_dims ? B_meta.last_dims[idx] : B_meta.uniform_last;
1351	  int64_t d_first = D_meta.first_dims ? D_meta.first_dims[idx] : D_meta.uniform_first;
1352	  int64_t d_last = D_meta.last_dims ? D_meta.last_dims[idx] : D_meta.uniform_last;
1353	
1354	  // Compute offsets (from explicit array, cumulative from per-tensor dims, or uniform)
1355	  int64_t a_offset = a_is_discrete ? 0 : compute_grouped_tensor_offset(A_meta, idx);
1356	  int64_t b_offset = compute_grouped_tensor_offset(B_meta, idx);
1357	  int64_t c_offset = compute_grouped_tensor_offset(C_meta, idx);
1358	  int64_t d_offset = compute_grouped_tensor_offset(D_meta, idx);
1359	
1360	  // Compute data pointers
1361	  A_ptrs[idx] = a_is_discrete
1362	                    ? a_multi_tensor_args.data_ptrs[idx]
1363	                    : (a_base == nullptr ? nullptr : a_base + (a_offset * a_bits_per_elem) / 8);
1364	  B_ptrs[idx] = b_base == nullptr ? nullptr : b_base + (b_offset * b_bits_per_elem) / 8;
1365	  C_ptrs[idx] = c_is_discrete ? c_multi_tensor_args.data_ptrs[idx]
1366	                              : (c_base == nullptr ? nullptr : c_base + c_offset * c_elem_size);
1367	  D_ptrs[idx] = d_is_discrete ? d_multi_tensor_args.data_ptrs[idx]
1368	                              : (d_base == nullptr ? nullptr : d_base + d_offset * d_elem_size);
1369	
1370	  // Compute storage dimensions for cuBLAS matrix layouts from logical dims.
1371	  // Rowwise and MXFP8 columnwise storage use logical row-major layout, viewed as
1372	  // column-major rows=last, cols=first. Transposed columnwise storage reverses this.
1373	  if (a_is_discrete) {
1374	    a_rows[idx] = a_multi_tensor_args.rows[idx];
1375	    a_cols[idx] = a_multi_tensor_args.cols[idx];
1376	  } else if (a_storage_transposed) {
1377	    a_rows[idx] = static_cast<int>(a_first);
1378	    a_cols[idx] = static_cast<int>(a_last);
1379	  } else {
1380	    a_rows[idx] = static_cast<int>(a_last);
1381	    a_cols[idx] = static_cast<int>(a_first);
1382	  }
1383	  if (b_storage_transposed) {
1384	    b_rows[idx] = static_cast<int>(b_first);
1385	    b_cols[idx] = static_cast<int>(b_last);
1386	  } else {
1387	    b_rows[idx] = static_cast<int>(b_last);
1388	    b_cols[idx] = static_cast<int>(b_first);
1389	  }
1390	  if (d_is_discrete) {
